    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "Undoes all changes of the last apply that still exist.",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Before applying:|r |cff90ff90%s|r   »   |cffffd100Now:|r |cffff9090%s|r",
