    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "Puts only this change into the template. The other characters see it at their next login.",
    ["Zurücksetzen"] = "Reset",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "Resets only this setting on this character to the template.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100In the template:|r %s   »   |cffffd100Now:|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100Template:|r |cff90ff90%s|r   »   |cffffd100This character:|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(since login at %s)",
