    ["Keine Änderungen seit dem Einloggen."] = "No changes since logging in.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Before:|r |cff90ff90%s|r   »   |cffffd100Now:|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "Applies to all characters. Right-click: never track.",
    ["Übernehmen"] = "Accept",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "Remembers the new value as the state; the line disappears.",
    ["Stellt den vorherigen Wert wieder her."] = "Restores the previous value.",
    ["Abgewählt (%d)"] = "Excluded (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "No template saved yet. Log in with the character whose settings should apply to all and click \"Save as general template\" on the left. For macros and action bars, save one class template per class.",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "No differences – this character matches the templates.",
    ["%d Abweichungen, %d angehakt"] = "%d differences, %d ticked",
    ["%d Änderungen seit der Vorlage"] = "%d changes since the template",
    ["%d accountweit"] = "%d account-wide",
    ["%d Einstellung(en) abgewählt"] = "%d setting(s) unticked",
    ["%d Änderung(en) übernommen."] = "%d change(s) accepted.",
    ["Speichert die Einstellungen des aktuellen Chars als Vorlage und überträgt sie auf die anderen Chars, sobald diese sich einloggen. Makros und Aktionsleisten gehen nur an Chars derselben Klasse. Vor dem Übernehmen siehst du für jede Einstellung vorher und nachher und kannst sie einzeln abwählen.\n\nBefehle: /charsync (Fenster), /charsync save (allgemeine Vorlage), /charsync saveclass (Klassen-Vorlage), /charsync apply (übernehmen)"] = "Saves the settings of the current character as a template and copies them to your other characters when they log in. Macros and action bars only go to characters of the same class. Before applying, you see before and after for every setting and can untick each one.\n\nCommands: /charsync (window), /charsync save (general template), /charsync saveclass (class template), /charsync apply (apply)",
    ["CharSync-Fenster öffnen"] = "Open CharSync window",
    ["Neue Vorlage zum Prüfen"] = "New template to review",
