    ["Leert diesen Platz, weil er beim Vorlage-Char frei ist."] = "Vide cet emplacement, car il est vide sur le personnage modèle.",
    ["Legt „%s“ auf diesen Platz der Aktionsleiste, wie beim Vorlage-Char."] = "Place « %s » sur cet emplacement de la barre d'action, comme sur le personnage modèle.",
    ["konnte „%s“ nicht aufnehmen"] = "impossible de prendre « %s »",
    ["Interface-Optionen"] = "Options d'interface",
    ["Optionen, die WoW pro Charakter speichert: zusätzliche Aktionsleisten, persönliche Ressourcenanzeige, Questlevel, Raidframe-Optionen, Weltkarte, Minimap. Grafik, Sound und die meisten anderen Optionen gelten ohnehin für alle Chars."] = "Options que WoW enregistre par personnage : barres d'action supplémentaires, affichage des ressources personnelles, niveau des quêtes, options des cadres de raid, carte du monde, minicarte. Graphismes, son et la plupart des autres options s'appliquent de toute façon à tous les personnages.",
    ["Chatfenster & Farben"] = "Fenêtres de discussion et couleurs",
    ["Chat-Tabs (Name, Schriftgröße, Hintergrund), welche Nachrichtenarten und Kanäle darin erscheinen und die Farben der Chat-Arten. Fehlende Kanäle werden betreten."] = "Onglets de discussion (nom, taille de police, fond), types de messages et canaux qui y apparaissent et couleurs des types de discussion. Les canaux manquants sont rejoints.",
    ["Edit-Mode-Layout"] = "Disposition du mode Édition",
    ["Welches Edit-Mode-Layout aktiv ist. Die Layouts selbst sind accountweit, nur die Auswahl ist pro Char."] = "Quelle disposition du mode Édition est active. Les dispositions elles-mêmes sont communes au compte, seul le choix est par personnage.",
    ["Tastenbelegung"] = "Raccourcis",
    ["Alle Tastenbelegungen. Nutzen alle Chars die accountweite Belegung, gibt es hier keine Abweichungen – wichtig nur für Chars mit charakterspezifischer Belegung."] = "Tous les raccourcis. Si tous les personnages utilisent les raccourcis communs au compte, il n'y a aucune différence ici – cela ne concerne que les personnages avec des raccourcis propres.",
    ["Addon-Auswahl"] = "Addons activés",
    ["Welche Addons bei diesem Char aktiviert sind (Addon-Menü am Charakterauswahl-Bildschirm). Wird nach einem Neuladen aktiv."] = "Quels addons sont activés pour ce personnage (menu AddOns de l'écran de sélection des personnages). Prend effet après un rechargement.",
    ["Addon-Profile (Ace3)"] = "Profils d'addons (Ace3)",
    ["Welches Profil Addons nutzen, die ihre Einstellungen über die Bibliothek Ace3 speichern. Mit dem Profil des Vorlage-Chars teilen sich beide alle Einstellungen dieses Addons, auch Fensterpositionen und das Minimap-Icon."] = "Le profil utilisé par les addons qui enregistrent leurs réglages avec la bibliothèque Ace3. Avec le profil du personnage modèle, les deux partagent tous les réglages de cet addon, y compris les positions des fenêtres et le bouton de la minicarte.",
    ["Fensterpositionen"] = "Positions des fenêtres",
    ["Wo verschiebbare Fenster stehen, deren Position WoW pro Char merkt (Fenster von WoW und von Addons). Positionen, die ein Addon selbst accountweit speichert, gelten ohnehin für alle Chars."] = "L'emplacement des fenêtres déplaçables dont WoW retient la position par personnage (fenêtres de WoW et des addons). Les positions qu'un addon enregistre lui-même pour tout le compte valent déjà pour tous les personnages.",
    ["Makros"] = "Macros",
    ["Charakterspezifische Makros – nur zwischen Chars derselben Klasse. Fehlende Makros werden angelegt, abweichende angepasst. Makros, die es beim Vorlage-Char nicht gibt, werden nur gelöscht, wenn du sie ausdrücklich anhakst."] = "Macros propres au personnage – uniquement entre personnages de la même classe. Les macros manquantes sont créées, celles qui diffèrent sont mises à jour. Les macros absentes du personnage modèle ne sont supprimées que si vous les cochez explicitement.",
    ["Aktionsleisten"] = "Barres d'action",
    ["Was auf den Aktionsleisten liegt – nur zwischen Chars derselben Klasse. Fähigkeiten, die dieser Char noch nicht kennt, und Makros, die es hier nicht gibt, werden übersprungen."] = "Contenu des barres d'action – uniquement entre personnages de la même classe. Les techniques que ce personnage ne connaît pas encore et les macros qu'il n'a pas sont ignorées.",
    ["Accountweite Einstellungen"] = "Réglages du compte",
    ["Fenster nicht gefunden"] = "Fenêtre introuvable",
    ["(nicht gesetzt)"] = "(non défini)",
    ["WoW-Optionen (accountweit)"] = "Options de WoW (tout le compte)",
    ["Minimap-Icons"] = "Boutons de la minicarte",
    ["(kein Makro)"] = "(aucune macro)",
    ["(leer)"] = "(vide)",
    ["Makro-Text:"] = "Texte de la macro :",
    ["In der Vorlage:"] = "Dans le modèle :",
    ["Jetzt:"] = "Maintenant :",
    ["Vorlage:"] = "Modèle :",
    ["Dieser Char:"] = "Ce personnage :",
    ["Abgewählt: wird nie synchronisiert bzw. nicht verfolgt."] = "Exclu : jamais synchronisé ni suivi.",
    ["Haken setzen: wieder einbeziehen."] = "Coche pour l'inclure à nouveau.",
    ["|cffffd100Vorher:|r %s"] = "|cffffd100Avant :|r %s",
    ["|cffffd100Jetzt:|r %s"] = "|cffffd100Maintenant :|r %s",
    ["Zurücksetzen = alten Wert wiederherstellen. Übernehmen = neuen Wert als Stand merken."] = "Réinitialiser = rétablir l'ancienne valeur. Accepter = retenir la nouvelle valeur comme état.",
    ["Rechtsklick: diese Einstellung nie verfolgen."] = "Clic droit : ne jamais suivre ce réglage.",
    ["Intern: %s"] = "Interne : %s",
    ["Macht nur diese Änderung der letzten Übernahme rückgängig."] = "Annule uniquement ce changement de la dernière application.",
    ["|cffffd100Vor der Übernahme:|r %s"] = "|cffffd100Avant l'application :|r %s",
    ["Vor der Übernahme:"] = "Avant l'application :",
    ["Seit dem Speichern der Vorlage geändert. Mit „Vorlage aktualisieren“ geht diese Änderung an die anderen Chars."] = "Modifié depuis l'enregistrement du modèle. « Mettre à jour le modèle » transmet ce changement aux autres personnages.",
    ["|cffffd100In der Vorlage:|r %s"] = "|cffffd100Dans le modèle :|r %s",
    ["|cffffd100Vorlage (%s):|r %s"] = "|cffffd100Modèle (%s) :|r %s",
    ["|cffffd100Dieser Char:|r %s"] = "|cffffd100Ce personnage :|r %s",
    ["Beim Übernehmen: %s"] = "En appliquant : %s",
    ["Nicht möglich: %s"] = "Impossible : %s",
    ["Wird nur übernommen, wenn du den Haken ausdrücklich setzt."] = "Appliqué uniquement si vous le cochez explicitement.",
    ["Wird nach einem Neuladen der Oberfläche vollständig aktiv."] = "Prend pleinement effet après un rechargement de l'interface.",
    ["Haken entfernen = diese Einstellung nie synchronisieren (gilt für alle Chars)."] = "Décocher = ne jamais synchroniser ce réglage (pour tous les personnages).",
    ["Alles in diesem Abschnitt anhaken oder abwählen."] = "Cocher ou décocher tout dans cette section.",
    ["Vorlage für %s"] = "Modèle pour %s",
    ["Allgemeine Vorlage"] = "Modèle général",
    ["noch keine"] = "aucun pour l'instant",
    ["(dieser Char)"] = "(ce personnage)",
    ["%d.%m.%Y um %H:%M"] = "%d/%m/%Y à %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync – copier les réglages sur tous les personnages",
    ["Als allgemeine Vorlage speichern"] = "Enregistrer comme modèle général",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "Enregistre tous les réglages de ce personnage tels qu'ils sont : le modèle général et le modèle de sa classe (si ce personnage le fournit). Les réglages du compte ne sont pas modifiés – valide-les avec les boutons en bas à droite.",
    ["Als Klassen-Vorlage speichern"] = "Enregistrer comme modèle de classe",
    ["Klassen-Vorlage"] = "Modèle de classe",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "Enregistre les macros et barres d'action de ce personnage comme modèle pour tous les personnages de la classe %s.",
    ["Allgemeiner Vorlage-Char"] = "Personnage modèle général",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "Ce personnage fournit le modèle général. Avec « Mettre à jour le modèle automatiquement », il est enregistré automatiquement, sinon avec le bouton ou un par un avec « Vers le modèle ».",
    ["Vorlage-Char seiner Klasse"] = "Personnage modèle de sa classe",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "Ce personnage fournit les macros et barres d'action de sa classe. Avec « Mettre à jour le modèle automatiquement », ce modèle est enregistré automatiquement.",
    ["Ohne Nachfrage übernehmen"] = "Appliquer sans demander",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "Les nouveaux modèles sont appliqués dès la connexion, sans ouvrir cette fenêtre de vérification.",
    ["Vorlage automatisch aktualisieren"] = "Mettre à jour le modèle automatiquement",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "Les personnages modèles enregistrent leur modèle une fois par minute et à la déconnexion si quelque chose a changé. Par défaut : désactivé.",
    ["Minimap-Icon anzeigen"] = "Afficher le bouton de la minicarte",
    ["Zeigt das CharSync-Icon an der Minimap. Ein Klick darauf öffnet dieses Fenster."] = "Affiche le bouton CharSync sur la minicarte. Un clic ouvre cette fenêtre.",
    ["Bereiche"] = "Sections",
    ["(gleiche Klasse)"] = "(même classe)",
    ["Verfolgt Einstellungen, die für alle Chars gelten (accountweite Addon-Einstellungen, accountweite WoW-Optionen): Bei jedem Einloggen merkt sich CharSync den Stand, danach erscheint hier jede Änderung mit vorherigem Wert – einzeln übernehmen oder zurücksetzen, ausgewählte oder alle. Standard: aus."] = "Suit les réglages valables pour tous les personnages (réglages d'addons et options de WoW du compte) : à chaque connexion, CharSync retient l'état actuel ; ensuite chaque changement apparaît ici avec sa valeur précédente – à accepter ou réinitialiser un par un, la sélection ou tout. Par défaut : désactivé.",
    ["Abgewählte Einstellungen"] = "Réglages exclus",
    ["Zeigt am Ende der Liste die Einstellungen, die du abgewählt hast (nie synchronisieren, nie verfolgen). Ein Haken dort holt sie zurück."] = "Affiche à la fin de la liste les réglages que tu as exclus (jamais synchronisés, jamais suivis). Les cocher les réactive.",
    ["Vergleich: dieser Char » Vorlage"] = "Comparaison : ce personnage » modèle",
    ["Alle anhaken"] = "Tout cocher",
    ["Hakt alles in der Liste an. Abgewählte Einstellungen bleiben abgewählt."] = "Coche tout dans la liste. Les réglages exclus restent exclus.",
    ["Keine"] = "Aucun",
    ["Entfernt alle Haken in der Liste."] = "Retire toutes les coches de la liste.",
    ["Angehakte übernehmen"] = "Appliquer la sélection",
    ["Übernimmt alles Angehakte: Abweichungen zur Vorlage werden übernommen, accountweite Einstellungen werden der neue Stand, Änderungen seit der Vorlage gehen in die Vorlage."] = "Applique tout ce qui est coché : les différences avec le modèle sont appliquées, les réglages du compte deviennent le nouvel état, les changements depuis le modèle vont dans le modèle.",
    ["Alle übernehmen"] = "Tout appliquer",
    ["Übernimmt alles in der Liste: Abweichungen zur Vorlage (außer nie zu synchronisierenden), accountweite Einstellungen als neuen Stand, Änderungen seit der Vorlage in die Vorlage."] = "Applique tout ce qui est dans la liste : différences avec le modèle (sauf celles à ne jamais synchroniser), réglages du compte comme nouvel état, changements depuis le modèle dans le modèle.",
    ["Alle zurücksetzen"] = "Tout réinitialiser",
    ["Setzt alle zurücksetzbaren Änderungen in der Liste zurück: Änderungen seit der Vorlage, die letzte Übernahme und accountweite Einstellungen."] = "Réinitialise tous les changements réinitialisables de la liste : changements depuis le modèle, dernière application et réglages du compte.",
    ["Ausgewählte zurücksetzen"] = "Réinitialiser la sélection",
    ["Setzt nur die angehakten Änderungen zurück."] = "Réinitialise uniquement les changements cochés.",
    ["Schließt das Fenster. Beim nächsten Login wirst du wieder gefragt."] = "Ferme la fenêtre. La question vous sera reposée à la prochaine connexion.",
    ["Diesmal nichts"] = "Pas cette fois",
    ["Übernimmt nichts und fragt erst wieder, wenn eine neuere Vorlage gespeichert wird."] = "N'applique rien et ne redemande qu'une fois qu'un modèle plus récent est enregistré.",
    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "Nouveau modèle de %s – vérifiez ce qui doit être appliqué.",
    ["Einstellungen dieses Chars (%s, %s)"] = "Réglages de ce personnage (%s, %s)",
    ["Als Vorlage für %s speichern"] = "Enregistrer comme modèle pour %s",
    ["Vorlage-Char für %s"] = "Personnage modèle pour %s",
    ["Letzte Übernahme vom %s"] = "Dernière application le %s",
    ["Alles rückgängig"] = "Tout annuler",
    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "Annule tous les changements encore présents de la dernière application.",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Avant l'application :|r |cff90ff90%s|r   »   |cffffd100Maintenant :|r |cffff9090%s|r",
    ["Rückgängig"] = "Annuler",
    ["(Klassen-Vorlage)"] = "(modèle de classe)",
    ["(seit der Vorlage geändert)"] = "(modifié depuis le modèle)",
    ["In Vorlage"] = "Vers le modèle",
    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "Ajoute uniquement ce changement au modèle. Les autres personnages le verront à leur prochaine connexion.",
    ["Zurücksetzen"] = "Réinitialiser",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "Remet uniquement ce réglage de ce personnage à l'état du modèle.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100Dans le modèle :|r %s   »   |cffffd100Maintenant :|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100Modèle :|r |cff90ff90%s|r   »   |cffffd100Ce personnage :|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(depuis la connexion le %s)",
    ["Wird gelesen …"] = "Lecture …",
    ["Keine Änderungen seit dem Einloggen."] = "Aucun changement depuis la connexion.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Avant :|r |cff90ff90%s|r   »   |cffffd100Maintenant :|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "Vaut pour tous les personnages. Clic droit : ne jamais suivre.",
    ["Übernehmen"] = "Accepter",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "Retient la nouvelle valeur comme état ; la ligne disparaît.",
    ["Stellt den vorherigen Wert wieder her."] = "Rétablit la valeur précédente.",
    ["Abgewählt (%d)"] = "Exclus (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "Aucun modèle enregistré pour l'instant. Connectez-vous avec le personnage dont les réglages doivent s'appliquer à tous et cliquez à gauche sur « Enregistrer comme modèle général ». Pour les macros et barres d'action, enregistrez un modèle de classe par classe.",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "Aucune différence – ce personnage correspond aux modèles.",
    ["%d Abweichungen, %d angehakt"] = "%d différences, %d cochées",
    ["%d Änderungen seit der Vorlage"] = "%d changements depuis le modèle",
    ["%d accountweit"] = "%d du compte",
    ["%d Einstellung(en) abgewählt"] = "%d réglage(s) décoché(s)",
    ["%d Änderung(en) übernommen."] = "%d changement(s) accepté(s).",
    ["Speichert die Einstellungen des aktuellen Chars als Vorlage und überträgt sie auf die anderen Chars, sobald diese sich einloggen. Makros und Aktionsleisten gehen nur an Chars derselben Klasse. Vor dem Übernehmen siehst du für jede Einstellung vorher und nachher und kannst sie einzeln abwählen.\n\nBefehle: /charsync (Fenster), /charsync save (allgemeine Vorlage), /charsync saveclass (Klassen-Vorlage), /charsync apply (übernehmen)"] = "Enregistre les réglages du personnage actuel comme modèle et les copie sur vos autres personnages lorsqu'ils se connectent. Les macros et barres d'action ne vont qu'aux personnages de la même classe. Avant d'appliquer, vous voyez l'avant et l'après de chaque réglage et pouvez décocher chacun d'eux.\n\nCommandes : /charsync (fenêtre), /charsync save (modèle général), /charsync saveclass (modèle de classe), /charsync apply (appliquer)",
    ["CharSync-Fenster öffnen"] = "Ouvrir la fenêtre CharSync",
    ["Neue Vorlage zum Prüfen"] = "Nouveau modèle à vérifier",
    ["Klicken: Fenster öffnen"] = "Clic : ouvrir la fenêtre",
    ["Ziehen: Icon verschieben"] = "Glisser : déplacer le bouton",
    ["Minimap-Icon zurückgesetzt."] = "Bouton de la minicarte réinitialisé.",
    ["Hauptleiste"] = "Barre principale",
    ["Hauptleiste Seite 2"] = "Barre principale page 2",
    ["Leiste rechts"] = "Barre de droite",
    ["Leiste rechts 2"] = "Barre de droite 2",
    ["Leiste unten rechts"] = "Barre en bas à droite",
    ["Leiste unten links"] = "Barre en bas à gauche",
    ["Haltungs-/Gestaltleiste 1"] = "Barre de posture/forme 1",
    ["Haltungs-/Gestaltleiste 2"] = "Barre de posture/forme 2",
    ["Haltungs-/Gestaltleiste 3"] = "Barre de posture/forme 3",
    ["Haltungs-/Gestaltleiste 4"] = "Barre de posture/forme 4",
    ["Leiste"] = "Barre",
}
T.esES = {
    ["Standard"] = "Predeterminado",
    ["An"] = "Activado",
    ["Aus"] = "Desactivado",
    ["keine"] = "ninguno",
    ["Auswahl %s"] = "Selección %s",
    ["Liste"] = "Lista",
    ["WoW-Einstellung, die pro Charakter gespeichert wird (CVar „%s“). Zu ihr ist keine Beschreibung hinterlegt."] = "Ajuste de WoW guardado por personaje (CVar «%s»). No hay descripción disponible.",
    ["blendet ein: %s"] = "muestra: %s",
    ["blendet aus: %s"] = "oculta: %s",
    ["schaltet ein"] = "lo activa",
    ["schaltet aus"] = "lo desactiva",
    ["stellt „%s“ auf „%s“ um"] = "cambia «%s» a «%s»",
    ["Zusätzliche Aktionsleisten"] = "Barras de acción adicionales",
    ["Blendet die zusätzlichen Aktionsleisten ein oder aus (Optionen > Aktionsleisten). Die Belegung der Leisten bleibt, wie sie ist – sie liegt auf dem Server."] = "Muestra u oculta las barras de acción adicionales (Opciones > Barras de acción). Lo que hay en las barras no cambia: eso se guarda en el servidor.",
    ["Persönliche Ressourcenanzeige"] = "Barra de recursos personal",
    ["Zeigt unter deinem Charakter eine eigene Leiste mit Gesundheit und Mana/Energie (eigene Namensplakette)."] = "Muestra debajo de tu personaje una barra con tu salud y maná/energía (tu propia placa de nombre).",
    ["Questlevel anzeigen"] = "Mostrar nivel de misión",
    ["Zeigt im Questlog und im Questtracker das Level jeder Quest vor dem Namen an."] = "Muestra el nivel de cada misión delante de su nombre en el registro de misiones y en el seguimiento de misiones.",
    ["Raidframes: Klassenfarben"] = "Marcos de banda: colores de clase",
    ["Färbt die Gesundheitsleisten in Gruppen- und Schlachtzugsfenstern in der Klassenfarbe statt grün."] = "Colorea las barras de salud de los marcos de grupo y de banda con el color de la clase en lugar de verde.",
    ["Raidframes: Kraftleisten"] = "Marcos de banda: barras de poder",
    ["Zeigt in Gruppen- und Schlachtzugsfenstern unter der Gesundheit eine Leiste für Mana, Wut oder Energie."] = "Muestra una barra de maná, ira o energía debajo de la salud en los marcos de grupo y de banda.",
    ["Raidframes: nur entfernbare Schwächungen"] = "Marcos de banda: solo perjuicios disipables",
    ["Zeigt in den Raidframes nur Schwächungen, die du selbst entfernen kannst."] = "Muestra en los marcos de banda solo los perjuicios que puedes quitar tú.",
    ["Raidframes: Gesundheitstext"] = "Marcos de banda: texto de salud",
    ["Welcher Text in den Raidframes auf der Gesundheitsleiste steht (keiner, Gesundheit, verlorene Gesundheit, Prozent)."] = "Qué texto muestran los marcos de banda en la barra de salud (ninguno, salud, salud perdida, porcentaje).",
    ["Raidframes: Begleiter anzeigen"] = "Marcos de banda: mostrar mascotas",
    ["Zeigt die Begleiter der Gruppenmitglieder als eigene Raidframes."] = "Muestra las mascotas de los miembros del grupo en sus propios marcos de banda.",
    ["Raidframes: Haupttank und -assistent"] = "Marcos de banda: tanque y asistente principal",
    ["Zeigt Haupttank und Hauptassistent als eigene Raidframes."] = "Muestra al tanque principal y al asistente principal en sus propios marcos de banda.",
    ["Gruppenfenster im Raid-Stil"] = "Marcos de grupo estilo banda",
    ["Nutzt für die Gruppe dieselben kompakten Fenster wie im Schlachtzug."] = "Usa para el grupo los mismos marcos compactos que en una banda.",
    ["Karte beim Laufen ausblenden"] = "Atenuar mapa al moverse",
    ["Macht die geöffnete Weltkarte durchsichtig, während du dich bewegst."] = "Hace transparente el mapa del mundo abierto mientras te mueves.",
    ["Kleine Weltkarte"] = "Mapa del mundo pequeño",
    ["Öffnet die Weltkarte als kleines Fenster statt als großes Vollbild."] = "Abre el mapa del mundo en una ventana pequeña en lugar de a pantalla completa.",
    ["Minimap-Verfolgung"] = "Rastreo del minimapa",
    ["Was die Minimap anzeigt, z. B. Briefkasten, Lehrer, Händler, Gasthäuser (Lupe an der Minimap). Kräuter- und Erzsuche hängen vom Beruf ab und bleiben dabei unverändert."] = "Lo que muestra el minimapa, p. ej. buzón, instructores, vendedores, posadas (lupa del minimapa). Buscar hierbas y Buscar minerales dependen de la profesión y no cambian.",
    ["Minimap-Zoom (draußen)"] = "Zoom del minimapa (exterior)",
    ["Zoomstufe der Minimap im Freien (0 = ganz herausgezoomt, 5 = ganz hineingezoomt)."] = "Nivel de zoom del minimapa al aire libre (0 = zoom mínimo, 5 = zoom máximo).",
    ["Minimap-Zoom (drinnen)"] = "Zoom del minimapa (interior)",
    ["Zoomstufe der Minimap in Gebäuden und Höhlen."] = "Nivel de zoom del minimapa en edificios y cuevas.",
    ["Abklingzeiten-Manager"] = "Gestor de tiempos de reutilización",
    ["Blendet die Blizzard-Leiste ein, die die Abklingzeiten deiner wichtigsten Fähigkeiten anzeigt."] = "Muestra la barra de Blizzard con los tiempos de reutilización de tus habilidades más importantes.",
    ["Geschlossene Tipps"] = "Consejos cerrados",
    ["Merkt sich, welche Hilfe-Tipps und Tutorial-Fenster du schon weggeklickt hast. Übernehmen heißt: diese Tipps tauchen auch bei diesem Char nicht mehr auf."] = "Recuerda qué consejos de ayuda y ventanas de tutorial ya has cerrado. Aplicarlo significa que esos consejos tampoco aparecerán en este personaje.",
    ["Leiste 2 (unten links)"] = "Barra 2 (abajo a la izquierda)",
    ["Leiste 3 (unten rechts)"] = "Barra 3 (abajo a la derecha)",
    ["Leiste 4 (rechts)"] = "Barra 4 (derecha)",
    ["Leiste 5 (rechts 2)"] = "Barra 5 (derecha 2)",
    ["Leiste 6"] = "Barra 6",
    ["Leiste 7"] = "Barra 7",
    ["Leiste 8"] = "Barra 8",
    ["Fehler beim Speichern von „%s“: %s"] = "Error al guardar «%s»: %s",
    ["Makros und Aktionsleisten von %s als Vorlage für %s gespeichert."] = "Macros y barras de acción de %s guardadas como plantilla para %s.",
    ["Vorlage von %s gespeichert. Andere Chars übernehmen sie beim nächsten Login."] = "Plantilla de %s guardada. Los demás personajes la aplicarán en su próximo inicio de sesión.",
    ["Vorlage automatisch gespeichert (%d Änderungen)."] = "Plantilla guardada automáticamente (%d cambios).",
    ["Fehler beim Vergleichen"] = "Error al comparar",
    ["Es ist noch keine Vorlage gespeichert."] = "Todavía no hay ninguna plantilla guardada.",
    ["Im Kampf – die Einstellungen werden nach dem Kampf übernommen."] = "En combate: los ajustes se aplicarán después del combate.",
    ["|cffff6060Nicht übernommen:|r %s (%s)"] = "|cffff6060No aplicado:|r %s (%s)",
    ["%d Einstellung(en) übernommen, %d nicht möglich."] = "%d ajuste(s) aplicado(s), %d no posible(s).",
    ["%d Einstellung(en) übernommen."] = "%d ajuste(s) aplicado(s).",
    ["Im Kampf nicht möglich."] = "No es posible en combate.",
    ["„%s“ in die Vorlage übernommen."] = "«%s» añadido a la plantilla.",
    ["„%s“ zurückgesetzt."] = "«%s» restablecido.",
    ["„%s“ rückgängig gemacht."] = "«%s» deshecho.",
    ["%d Einstellung(en) zurückgesetzt."] = "%d ajuste(s) restablecido(s).",
    ["%d Änderung(en) rückgängig gemacht."] = "%d cambio(s) deshecho(s).",
    ["|cff33ccffCharSync|r\n\nEinige Änderungen (Addons, Profile, Edit-Mode) werden erst nach einem Neuladen der Oberfläche vollständig aktiv.\n\nJetzt neu laden?"] = "|cff33ccffCharSync|r\n\nAlgunos cambios (addons, perfiles, Modo Edición) solo surten efecto por completo tras recargar la interfaz.\n\n¿Recargar ahora?",
    ["Neu laden"] = "Recargar",
    ["Später"] = "Más tarde",
