    ["Chatfenster %d"] = "Ventana de chat %d",
    ["Stellt diesen Chat-Tab so ein wie beim Vorlage-Char: Name, Schrift, Hintergrund und welche Nachrichten und Kanäle darin erscheinen."] = "Configura esta pestaña de chat como en el personaje plantilla: nombre, fuente, fondo y qué mensajes y canales aparecen en ella.",
    ["Chatfarben"] = "Colores del chat",
    ["Färbt die Chat-Arten (Gilde, Gruppe, Flüstern …) wie beim Vorlage-Char."] = "Colorea los tipos de chat (hermandad, grupo, susurro…) como en el personaje plantilla.",
    ["Aktives Edit-Mode-Layout"] = "Diseño activo del Modo Edición",
    ["Wechselt das Edit-Mode-Layout. Damit sitzen Aktionsleisten, Minimap, Einheitenfenster, Chat und Taschen dort, wo sie im Layout des Vorlage-Chars sitzen."] = "Cambia el diseño del Modo Edición. Así las barras de acción, el minimapa, los marcos de unidad, el chat y las bolsas quedan donde están en el diseño del personaje plantilla.",
    ["Das Layout gibt es bei diesem Char nicht (Charakter-Layout des Vorlage-Chars)."] = "Este personaje no tiene ese diseño (es un diseño de personaje del personaje plantilla).",
    ["Layout nicht gefunden"] = "Diseño no encontrado",
    ["Taste %s"] = "Tecla %s",
    ["Belegt die Taste so wie beim Vorlage-Char."] = "Asigna la tecla como en el personaje plantilla.",
    ["Entfernt die Belegung dieser Taste, weil sie beim Vorlage-Char frei ist."] = "Quita la asignación de esta tecla porque en el personaje plantilla está libre.",
    ["entfernt „%s“"] = "quita «%s»",
    ["ersetzt „%s“ durch „%s“"] = "reemplaza «%s» por «%s»",
    ["belegt die Taste mit „%s“"] = "asigna la tecla a «%s»",
    ["Aktiviert das Addon „%s“ für diesen Char."] = "Activa el addon «%s» para este personaje.",
    ["Deaktiviert das Addon „%s“ für diesen Char. Seine Einstellungen bleiben erhalten."] = "Desactiva el addon «%s» para este personaje. Sus ajustes se conservan.",
    ["aktiv"] = "activado",
    ["aus"] = "desactivado",
    ["Über das Addon: %s"] = "Sobre el addon: %s",
    ["Profil von %s"] = "Perfil de %s",
    ["Wechselt %s bei diesem Char auf das Profil „%s“. Danach gelten hier dieselben Einstellungen wie beim Vorlage-Char – Änderungen wirken künftig bei beiden. Das bisherige Profil bleibt gespeichert."] = "Cambia %s en este personaje al perfil «%s». A partir de entonces se aplican aquí los mismos ajustes que en el personaje plantilla: los cambios futuros afectan a ambos. El perfil anterior se conserva.",
    ["Icon „%s“"] = "Botón «%s»",
    ["Fenster „%s“"] = "Ventana «%s»",
    ["Standardposition"] = "posición predeterminada",
    ["Das Fenster wurde bei diesem Char noch nicht geöffnet. Öffne es einmal, dann lässt sich die Position übernehmen."] = "Este personaje aún no ha abierto la ventana. Ábrela una vez y luego se podrá aplicar la posición.",
    ["Dieses Fenster kann ein Addon nicht verschieben (geschützt)."] = "Un addon no puede mover esta ventana (protegida).",
    ["Die Vorlage kennt dieses Icon noch nicht. Mit „In Vorlage“ übernimmst du seine Position."] = "La plantilla aún no conoce este botón. «A la plantilla» toma su posición.",
    ["Setzt das Fenster an dieselbe Stelle wie beim Vorlage-Char."] = "Coloca la ventana en el mismo sitio que en el personaje plantilla.",
    ["verschiebt das Fenster an die Position des Vorlage-Chars"] = "mueve la ventana a la posición del personaje plantilla",
    ["(+%d)"] = "(+%d)",
    ["Zeile %d: %s"] = "línea %d: %s",
    ["(ohne Namen)"] = "(sin nombre)",
    ["heißt „%s“"] = "se llama «%s»",
    ["Makro „%s“"] = "Macro «%s»",
    ["Ersetzt Text und Symbol dieses Makros durch die Fassung des Vorlage-Chars."] = "Sustituye el texto y el icono de esta macro por la versión del personaje plantilla.",
    ["Benennt das Makro um. Text und Symbol bleiben wie beim Vorlage-Char."] = "Cambia el nombre de la macro. El texto y el icono quedan como en el personaje plantilla.",
    ["Makro nicht gefunden"] = "Macro no encontrada",
    ["Kein Platz mehr für charakterspezifische Makros (höchstens %d)."] = "No queda espacio para más macros específicas del personaje (máximo %d).",
    ["wird angelegt"] = "se creará",
    ["Legt das Makro mit Symbol und Text wie beim Vorlage-Char an. Auf die Aktionsleiste kommt es über den Bereich „Aktionsleisten“."] = "Crea la macro con el icono y el texto como en el personaje plantilla. Llega a la barra de acción a través de la sección «Barras de acción».",
    ["wird gelöscht"] = "se borrará",
    ["Dieses Makro gibt es beim Vorlage-Char nicht. Es wird nur gelöscht, wenn du den Haken setzt."] = "El personaje plantilla no tiene esta macro. Solo se borra si la marcas.",
    ["%s, Platz %d"] = "%s, casilla %d",
    ["Gegenstand %d"] = "Objeto %d",
    ["leer"] = "vacía",
    ["Makro: %s"] = "Macro: %s",
    ["Ausrüstungsset: %s"] = "Equipamiento: %s",
    ["Ausklappleiste: %s"] = "Menú desplegable: %s",
    ["Vorlage ohne Aktionen"] = "Plantilla sin acciones",
    ["Die Vorlage enthält keine Aktionen. Speichere sie beim Vorlage-Char neu."] = "La plantilla no contiene acciones. Vuelve a guardarla en el personaje plantilla.",
    ["Diese Fähigkeit kennt dieser Char (noch) nicht."] = "Este personaje (todavía) no conoce esta habilidad.",
    ["Das Makro gibt es bei diesem Char nicht."] = "Este personaje no tiene esta macro.",
    ["Diese Art von Aktion kann nicht übertragen werden."] = "Este tipo de acción no se puede transferir.",
    ["leert diesen Platz („%s“ fällt weg)"] = "vacía esta casilla (se quita «%s»)",
    ["legt „%s“ auf diesen Platz"] = "pone «%s» en esta casilla",
    ["Leert diesen Platz, weil er beim Vorlage-Char frei ist."] = "Vacía esta casilla porque está libre en el personaje plantilla.",
    ["Legt „%s“ auf diesen Platz der Aktionsleiste, wie beim Vorlage-Char."] = "Pone «%s» en esta casilla de la barra de acción, como en el personaje plantilla.",
    ["konnte „%s“ nicht aufnehmen"] = "no se pudo coger «%s»",
    ["Interface-Optionen"] = "Opciones de interfaz",
    ["Optionen, die WoW pro Charakter speichert: zusätzliche Aktionsleisten, persönliche Ressourcenanzeige, Questlevel, Raidframe-Optionen, Weltkarte, Minimap. Grafik, Sound und die meisten anderen Optionen gelten ohnehin für alle Chars."] = "Opciones que WoW guarda por personaje: barras de acción adicionales, barra de recursos personal, nivel de misión, opciones de los marcos de banda, mapa del mundo, minimapa. Los gráficos, el sonido y la mayoría de las demás opciones ya se aplican a todos los personajes.",
    ["Chatfenster & Farben"] = "Ventanas de chat y colores",
    ["Chat-Tabs (Name, Schriftgröße, Hintergrund), welche Nachrichtenarten und Kanäle darin erscheinen und die Farben der Chat-Arten. Fehlende Kanäle werden betreten."] = "Pestañas de chat (nombre, tamaño de fuente, fondo), qué tipos de mensaje y canales aparecen en ellas y los colores de los tipos de chat. Te unirás a los canales que falten.",
    ["Edit-Mode-Layout"] = "Diseño del Modo Edición",
    ["Welches Edit-Mode-Layout aktiv ist. Die Layouts selbst sind accountweit, nur die Auswahl ist pro Char."] = "Qué diseño del Modo Edición está activo. Los diseños son de toda la cuenta; solo la elección es por personaje.",
    ["Tastenbelegung"] = "Asignación de teclas",
    ["Alle Tastenbelegungen. Nutzen alle Chars die accountweite Belegung, gibt es hier keine Abweichungen – wichtig nur für Chars mit charakterspezifischer Belegung."] = "Todas las asignaciones de teclas. Si todos los personajes usan las asignaciones de la cuenta, aquí no hay diferencias: solo importa para personajes con asignaciones específicas del personaje.",
    ["Addon-Auswahl"] = "Addons activados",
    ["Welche Addons bei diesem Char aktiviert sind (Addon-Menü am Charakterauswahl-Bildschirm). Wird nach einem Neuladen aktiv."] = "Qué addons están activados para este personaje (menú Accesorios en la pantalla de selección de personaje). Surte efecto tras recargar.",
    ["Addon-Profile (Ace3)"] = "Perfiles de addons (Ace3)",
    ["Welches Profil Addons nutzen, die ihre Einstellungen über die Bibliothek Ace3 speichern. Mit dem Profil des Vorlage-Chars teilen sich beide alle Einstellungen dieses Addons, auch Fensterpositionen und das Minimap-Icon."] = "Qué perfil usan los addons que guardan sus ajustes con la biblioteca Ace3. Con el perfil del personaje plantilla, ambos comparten todos los ajustes de ese addon, incluidas las posiciones de ventanas y el botón del minimapa.",
    ["Fensterpositionen"] = "Posiciones de ventanas",
    ["Wo verschiebbare Fenster stehen, deren Position WoW pro Char merkt (Fenster von WoW und von Addons). Positionen, die ein Addon selbst accountweit speichert, gelten ohnehin für alle Chars."] = "Dónde están las ventanas movibles cuya posición WoW recuerda por personaje (ventanas de WoW y de addons). Las posiciones que un addon guarda para toda la cuenta ya valen para todos los personajes.",
    ["Makros"] = "Macros",
    ["Charakterspezifische Makros – nur zwischen Chars derselben Klasse. Fehlende Makros werden angelegt, abweichende angepasst. Makros, die es beim Vorlage-Char nicht gibt, werden nur gelöscht, wenn du sie ausdrücklich anhakst."] = "Macros específicas del personaje: solo entre personajes de la misma clase. Las macros que faltan se crean y las distintas se actualizan. Las macros que el personaje plantilla no tiene solo se borran si las marcas expresamente.",
    ["Aktionsleisten"] = "Barras de acción",
    ["Was auf den Aktionsleisten liegt – nur zwischen Chars derselben Klasse. Fähigkeiten, die dieser Char noch nicht kennt, und Makros, die es hier nicht gibt, werden übersprungen."] = "Lo que hay en las barras de acción: solo entre personajes de la misma clase. Se omiten las habilidades que este personaje aún no conoce y las macros que no tiene.",
    ["Accountweite Einstellungen"] = "Ajustes de la cuenta",
    ["Fenster nicht gefunden"] = "Ventana no encontrada",
    ["(nicht gesetzt)"] = "(sin definir)",
    ["WoW-Optionen (accountweit)"] = "Opciones de WoW (toda la cuenta)",
    ["Minimap-Icons"] = "Botones del minimapa",
    ["(kein Makro)"] = "(sin macro)",
    ["(leer)"] = "(vacío)",
    ["Makro-Text:"] = "Texto de la macro:",
    ["In der Vorlage:"] = "En la plantilla:",
    ["Jetzt:"] = "Ahora:",
    ["Vorlage:"] = "Plantilla:",
    ["Dieser Char:"] = "Este personaje:",
    ["Abgewählt: wird nie synchronisiert bzw. nicht verfolgt."] = "Excluido: nunca se sincroniza ni se sigue.",
    ["Haken setzen: wieder einbeziehen."] = "Márcalo para volver a incluirlo.",
    ["|cffffd100Vorher:|r %s"] = "|cffffd100Antes:|r %s",
    ["|cffffd100Jetzt:|r %s"] = "|cffffd100Ahora:|r %s",
    ["Zurücksetzen = alten Wert wiederherstellen. Übernehmen = neuen Wert als Stand merken."] = "Restablecer = recuperar el valor anterior. Aceptar = recordar el nuevo valor como estado.",
    ["Rechtsklick: diese Einstellung nie verfolgen."] = "Clic derecho: no seguir nunca este ajuste.",
    ["Intern: %s"] = "Interno: %s",
    ["Macht nur diese Änderung der letzten Übernahme rückgängig."] = "Deshace solo este cambio de la última aplicación.",
    ["|cffffd100Vor der Übernahme:|r %s"] = "|cffffd100Antes de aplicar:|r %s",
    ["Vor der Übernahme:"] = "Antes de aplicar:",
    ["Seit dem Speichern der Vorlage geändert. Mit „Vorlage aktualisieren“ geht diese Änderung an die anderen Chars."] = "Cambiado desde que se guardó la plantilla. «Actualizar plantilla» envía este cambio a los demás personajes.",
    ["|cffffd100In der Vorlage:|r %s"] = "|cffffd100En la plantilla:|r %s",
    ["|cffffd100Vorlage (%s):|r %s"] = "|cffffd100Plantilla (%s):|r %s",
    ["|cffffd100Dieser Char:|r %s"] = "|cffffd100Este personaje:|r %s",
    ["Beim Übernehmen: %s"] = "Al aplicar: %s",
    ["Nicht möglich: %s"] = "No es posible: %s",
    ["Wird nur übernommen, wenn du den Haken ausdrücklich setzt."] = "Solo se aplica si lo marcas expresamente.",
    ["Wird nach einem Neuladen der Oberfläche vollständig aktiv."] = "Surte efecto por completo tras recargar la interfaz.",
    ["Haken entfernen = diese Einstellung nie synchronisieren (gilt für alle Chars)."] = "Desmarcar = no sincronizar nunca este ajuste (para todos los personajes).",
    ["Alles in diesem Abschnitt anhaken oder abwählen."] = "Marcar o desmarcar todo en esta sección.",
    ["Vorlage für %s"] = "Plantilla para %s",
    ["Allgemeine Vorlage"] = "Plantilla general",
    ["noch keine"] = "ninguna todavía",
    ["(dieser Char)"] = "(este personaje)",
    ["%d.%m.%Y um %H:%M"] = "%d/%m/%Y a las %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync – copia los ajustes a todos tus personajes",
    ["Als allgemeine Vorlage speichern"] = "Guardar como plantilla general",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "Guarda todos los ajustes de este personaje tal como están: la plantilla general y la plantilla de su clase (si este personaje la aporta). Los ajustes de la cuenta no se tocan: acéptalos con los botones de abajo a la derecha.",
    ["Als Klassen-Vorlage speichern"] = "Guardar como plantilla de clase",
    ["Klassen-Vorlage"] = "Plantilla de clase",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "Guarda las macros y barras de acción de este personaje como plantilla para todos los personajes de la clase %s.",
    ["Allgemeiner Vorlage-Char"] = "Personaje plantilla general",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "Este personaje aporta la plantilla general. Con «Actualizar plantilla automáticamente» se guarda sola; si no, con el botón o una a una con «A la plantilla».",
    ["Vorlage-Char seiner Klasse"] = "Personaje plantilla de su clase",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "Este personaje aporta las macros y barras de acción de su clase. Con «Actualizar plantilla automáticamente» esta plantilla se guarda sola.",
    ["Ohne Nachfrage übernehmen"] = "Aplicar sin preguntar",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "Las plantillas nuevas se aplican nada más iniciar sesión, sin abrir esta ventana para revisarlas.",
    ["Vorlage automatisch aktualisieren"] = "Actualizar plantilla automáticamente",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "Los personajes plantilla guardan su plantilla una vez por minuto y al cerrar sesión si algo ha cambiado. Por defecto: desactivado.",
    ["Minimap-Icon anzeigen"] = "Mostrar botón del minimapa",
    ["Zeigt das CharSync-Icon an der Minimap. Ein Klick darauf öffnet dieses Fenster."] = "Muestra el botón de CharSync en el minimapa. Al hacer clic se abre esta ventana.",
    ["Bereiche"] = "Secciones",
    ["(gleiche Klasse)"] = "(misma clase)",
    ["Verfolgt Einstellungen, die für alle Chars gelten (accountweite Addon-Einstellungen, accountweite WoW-Optionen): Bei jedem Einloggen merkt sich CharSync den Stand, danach erscheint hier jede Änderung mit vorherigem Wert – einzeln übernehmen oder zurücksetzen, ausgewählte oder alle. Standard: aus."] = "Sigue los ajustes que valen para todos los personajes (ajustes de addons y opciones de WoW de la cuenta): en cada conexión, CharSync recuerda el estado actual; después cada cambio aparece aquí con su valor anterior, para aceptarlo o restablecerlo uno a uno, los marcados o todos. Por defecto: desactivado.",
    ["Abgewählte Einstellungen"] = "Ajustes excluidos",
    ["Zeigt am Ende der Liste die Einstellungen, die du abgewählt hast (nie synchronisieren, nie verfolgen). Ein Haken dort holt sie zurück."] = "Muestra al final de la lista los ajustes que excluiste (no sincronizar, no seguir). Marcarlos ahí los recupera.",
    ["Vergleich: dieser Char » Vorlage"] = "Comparación: este personaje » plantilla",
    ["Alle anhaken"] = "Marcar todo",
    ["Hakt alles in der Liste an. Abgewählte Einstellungen bleiben abgewählt."] = "Marca todo en la lista. Los ajustes excluidos siguen excluidos.",
    ["Keine"] = "Ninguno",
    ["Entfernt alle Haken in der Liste."] = "Quita todas las marcas de la lista.",
    ["Angehakte übernehmen"] = "Aplicar marcados",
    ["Übernimmt alles Angehakte: Abweichungen zur Vorlage werden übernommen, accountweite Einstellungen werden der neue Stand, Änderungen seit der Vorlage gehen in die Vorlage."] = "Aplica todo lo marcado: las diferencias con la plantilla se aplican, los ajustes de la cuenta pasan a ser el nuevo estado y los cambios desde la plantilla van a la plantilla.",
    ["Alle übernehmen"] = "Aplicar todo",
    ["Übernimmt alles in der Liste: Abweichungen zur Vorlage (außer nie zu synchronisierenden), accountweite Einstellungen als neuen Stand, Änderungen seit der Vorlage in die Vorlage."] = "Aplica todo lo de la lista: diferencias con la plantilla (salvo las que no se sincronizan nunca), ajustes de la cuenta como nuevo estado, cambios desde la plantilla a la plantilla.",
    ["Alle zurücksetzen"] = "Restablecer todo",
    ["Setzt alle zurücksetzbaren Änderungen in der Liste zurück: Änderungen seit der Vorlage, die letzte Übernahme und accountweite Einstellungen."] = "Restablece todos los cambios restablecibles de la lista: cambios desde la plantilla, la última aplicación y los ajustes de la cuenta.",
    ["Ausgewählte zurücksetzen"] = "Restablecer marcados",
    ["Setzt nur die angehakten Änderungen zurück."] = "Restablece solo los cambios marcados.",
    ["Schließt das Fenster. Beim nächsten Login wirst du wieder gefragt."] = "Cierra la ventana. Se te volverá a preguntar en el próximo inicio de sesión.",
    ["Diesmal nichts"] = "Esta vez no",
    ["Übernimmt nichts und fragt erst wieder, wenn eine neuere Vorlage gespeichert wird."] = "No aplica nada y solo vuelve a preguntar cuando se guarde una plantilla más reciente.",
    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "Nueva plantilla de %s: revisa qué quieres aplicar.",
    ["Einstellungen dieses Chars (%s, %s)"] = "Ajustes de este personaje (%s, %s)",
    ["Als Vorlage für %s speichern"] = "Guardar como plantilla para %s",
    ["Vorlage-Char für %s"] = "Personaje plantilla para %s",
    ["Letzte Übernahme vom %s"] = "Última aplicación el %s",
    ["Alles rückgängig"] = "Deshacer todo",
    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "Deshace todos los cambios de la última aplicación que aún existen.",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Antes de aplicar:|r |cff90ff90%s|r   »   |cffffd100Ahora:|r |cffff9090%s|r",
    ["Rückgängig"] = "Deshacer",
    ["(Klassen-Vorlage)"] = "(plantilla de clase)",
    ["(seit der Vorlage geändert)"] = "(cambiado desde la plantilla)",
    ["In Vorlage"] = "A la plantilla",
    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "Pasa solo este cambio a la plantilla. Los demás personajes lo verán al conectarse.",
    ["Zurücksetzen"] = "Restablecer",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "Restablece solo este ajuste de este personaje al estado de la plantilla.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100En la plantilla:|r %s   »   |cffffd100Ahora:|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100Plantilla:|r |cff90ff90%s|r   »   |cffffd100Este personaje:|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(desde la conexión el %s)",
    ["Wird gelesen …"] = "Leyendo…",
    ["Keine Änderungen seit dem Einloggen."] = "No hay cambios desde que te conectaste.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Antes:|r |cff90ff90%s|r   »   |cffffd100Ahora:|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "Vale para todos los personajes. Clic derecho: no seguir nunca.",
