    ["Belegt die Taste so wie beim Vorlage-Char."] = "Assegna il tasto come sul personaggio modello.",
    ["Entfernt die Belegung dieser Taste, weil sie beim Vorlage-Char frei ist."] = "Rimuove l'assegnazione di questo tasto perché sul personaggio modello è libero.",
    ["entfernt „%s“"] = "rimuove “%s”",
    ["ersetzt „%s“ durch „%s“"] = "sostituisce “%s” con “%s”",
    ["belegt die Taste mit „%s“"] = "assegna il tasto a “%s”",
    ["Aktiviert das Addon „%s“ für diesen Char."] = "Attiva l'addon “%s” per questo personaggio.",
    ["Deaktiviert das Addon „%s“ für diesen Char. Seine Einstellungen bleiben erhalten."] = "Disattiva l'addon “%s” per questo personaggio. Le sue impostazioni vengono mantenute.",
    ["aktiv"] = "attivo",
    ["aus"] = "disattivato",
    ["Über das Addon: %s"] = "Informazioni sull'addon: %s",
    ["Profil von %s"] = "Profilo di %s",
    ["Wechselt %s bei diesem Char auf das Profil „%s“. Danach gelten hier dieselben Einstellungen wie beim Vorlage-Char – Änderungen wirken künftig bei beiden. Das bisherige Profil bleibt gespeichert."] = "Imposta %s su questo personaggio al profilo “%s”. Da quel momento valgono qui le stesse impostazioni del personaggio modello: le modifiche future riguarderanno entrambi. Il profilo precedente viene mantenuto.",
    ["Icon „%s“"] = "Pulsante “%s”",
    ["Fenster „%s“"] = "Finestra “%s”",
    ["Standardposition"] = "posizione predefinita",
    ["Das Fenster wurde bei diesem Char noch nicht geöffnet. Öffne es einmal, dann lässt sich die Position übernehmen."] = "Questo personaggio non ha ancora aperto la finestra. Aprila una volta, poi la posizione si potrà applicare.",
    ["Dieses Fenster kann ein Addon nicht verschieben (geschützt)."] = "Un addon non può spostare questa finestra (protetta).",
    ["Die Vorlage kennt dieses Icon noch nicht. Mit „In Vorlage“ übernimmst du seine Position."] = "Il modello non conosce ancora questo pulsante. «Nel modello» ne prende la posizione.",
    ["Setzt das Fenster an dieselbe Stelle wie beim Vorlage-Char."] = "Mette la finestra nello stesso punto del personaggio modello.",
    ["verschiebt das Fenster an die Position des Vorlage-Chars"] = "sposta la finestra nella posizione del personaggio modello",
    ["(+%d)"] = "(+%d)",
    ["Zeile %d: %s"] = "riga %d: %s",
    ["(ohne Namen)"] = "(senza nome)",
    ["heißt „%s“"] = "si chiama “%s”",
    ["Makro „%s“"] = "Macro “%s”",
    ["Ersetzt Text und Symbol dieses Makros durch die Fassung des Vorlage-Chars."] = "Sostituisce testo e icona di questa macro con la versione del personaggio modello.",
    ["Benennt das Makro um. Text und Symbol bleiben wie beim Vorlage-Char."] = "Rinomina la macro. Testo e icona restano come nel personaggio modello.",
    ["Makro nicht gefunden"] = "Macro non trovata",
    ["Kein Platz mehr für charakterspezifische Makros (höchstens %d)."] = "Non c'è più spazio per macro specifiche del personaggio (al massimo %d).",
    ["wird angelegt"] = "verrà creata",
    ["Legt das Makro mit Symbol und Text wie beim Vorlage-Char an. Auf die Aktionsleiste kommt es über den Bereich „Aktionsleisten“."] = "Crea la macro con icona e testo come sul personaggio modello. Finisce sulla barra delle azioni tramite la sezione “Barre delle azioni”.",
    ["wird gelöscht"] = "verrà eliminata",
    ["Dieses Makro gibt es beim Vorlage-Char nicht. Es wird nur gelöscht, wenn du den Haken setzt."] = "Il personaggio modello non ha questa macro. Viene eliminata solo se la spunti.",
    ["%s, Platz %d"] = "%s, posizione %d",
    ["Gegenstand %d"] = "Oggetto %d",
    ["leer"] = "vuoto",
    ["Makro: %s"] = "Macro: %s",
    ["Ausrüstungsset: %s"] = "Set di equipaggiamento: %s",
    ["Ausklappleiste: %s"] = "Menu a comparsa: %s",
    ["Vorlage ohne Aktionen"] = "Modello senza azioni",
    ["Die Vorlage enthält keine Aktionen. Speichere sie beim Vorlage-Char neu."] = "Il modello non contiene azioni. Salvalo di nuovo sul personaggio modello.",
    ["Diese Fähigkeit kennt dieser Char (noch) nicht."] = "Questo personaggio non conosce (ancora) questa abilità.",
    ["Das Makro gibt es bei diesem Char nicht."] = "Questo personaggio non ha questa macro.",
    ["Diese Art von Aktion kann nicht übertragen werden."] = "Questo tipo di azione non può essere trasferito.",
    ["leert diesen Platz („%s“ fällt weg)"] = "svuota questo spazio (“%s” viene rimosso)",
    ["legt „%s“ auf diesen Platz"] = "mette “%s” in questo spazio",
    ["Leert diesen Platz, weil er beim Vorlage-Char frei ist."] = "Svuota questa posizione perché sul personaggio modello è vuota.",
    ["Legt „%s“ auf diesen Platz der Aktionsleiste, wie beim Vorlage-Char."] = "Mette “%s” in questa posizione della barra delle azioni, come sul personaggio modello.",
    ["konnte „%s“ nicht aufnehmen"] = "impossibile prendere “%s”",
    ["Interface-Optionen"] = "Opzioni dell'interfaccia",
    ["Optionen, die WoW pro Charakter speichert: zusätzliche Aktionsleisten, persönliche Ressourcenanzeige, Questlevel, Raidframe-Optionen, Weltkarte, Minimap. Grafik, Sound und die meisten anderen Optionen gelten ohnehin für alle Chars."] = "Opzioni che WoW salva per personaggio: barre delle azioni aggiuntive, indicatore risorse personali, livello missioni, opzioni dei riquadri incursione, mappa del mondo, minimappa. Grafica, audio e la maggior parte delle altre opzioni valgono comunque per tutti i personaggi.",
    ["Chatfenster & Farben"] = "Finestre della chat e colori",
    ["Chat-Tabs (Name, Schriftgröße, Hintergrund), welche Nachrichtenarten und Kanäle darin erscheinen und die Farben der Chat-Arten. Fehlende Kanäle werden betreten."] = "Schede della chat (nome, dimensione carattere, sfondo), quali tipi di messaggi e canali vi compaiono e i colori dei tipi di chat. I canali mancanti vengono uniti.",
    ["Edit-Mode-Layout"] = "Disposizione della Modalità modifica",
    ["Welches Edit-Mode-Layout aktiv ist. Die Layouts selbst sind accountweit, nur die Auswahl ist pro Char."] = "Quale disposizione della Modalità modifica è attiva. Le disposizioni sono valide per tutto l'account, solo la scelta è per personaggio.",
    ["Tastenbelegung"] = "Assegnazione tasti",
    ["Alle Tastenbelegungen. Nutzen alle Chars die accountweite Belegung, gibt es hier keine Abweichungen – wichtig nur für Chars mit charakterspezifischer Belegung."] = "Tutte le assegnazioni dei tasti. Se tutti i personaggi usano le assegnazioni dell'account, qui non ci sono differenze: conta solo per i personaggi con assegnazioni specifiche.",
    ["Addon-Auswahl"] = "Addon attivi",
    ["Welche Addons bei diesem Char aktiviert sind (Addon-Menü am Charakterauswahl-Bildschirm). Wird nach einem Neuladen aktiv."] = "Quali addon sono attivi per questo personaggio (menu AddOn nella schermata di selezione del personaggio). Ha effetto dopo aver ricaricato.",
    ["Addon-Profile (Ace3)"] = "Profili degli addon (Ace3)",
    ["Welches Profil Addons nutzen, die ihre Einstellungen über die Bibliothek Ace3 speichern. Mit dem Profil des Vorlage-Chars teilen sich beide alle Einstellungen dieses Addons, auch Fensterpositionen und das Minimap-Icon."] = "Quale profilo usano gli addon che salvano le impostazioni con la libreria Ace3. Con il profilo del personaggio modello, entrambi condividono tutte le impostazioni di quell'addon, comprese posizioni delle finestre e pulsante della minimappa.",
    ["Fensterpositionen"] = "Posizioni delle finestre",
    ["Wo verschiebbare Fenster stehen, deren Position WoW pro Char merkt (Fenster von WoW und von Addons). Positionen, die ein Addon selbst accountweit speichert, gelten ohnehin für alle Chars."] = "Dove si trovano le finestre spostabili di cui WoW ricorda la posizione per personaggio (finestre di WoW e degli addon). Le posizioni che un addon salva da sé per tutto l'account valgono già per tutti i personaggi.",
    ["Makros"] = "Macro",
    ["Charakterspezifische Makros – nur zwischen Chars derselben Klasse. Fehlende Makros werden angelegt, abweichende angepasst. Makros, die es beim Vorlage-Char nicht gibt, werden nur gelöscht, wenn du sie ausdrücklich anhakst."] = "Macro specifiche del personaggio, solo tra personaggi della stessa classe. Le macro mancanti vengono create, quelle diverse aggiornate. Le macro che il personaggio modello non ha vengono eliminate solo se le spunti esplicitamente.",
    ["Aktionsleisten"] = "Barre delle azioni",
    ["Was auf den Aktionsleisten liegt – nur zwischen Chars derselben Klasse. Fähigkeiten, die dieser Char noch nicht kennt, und Makros, die es hier nicht gibt, werden übersprungen."] = "Il contenuto delle barre delle azioni, solo tra personaggi della stessa classe. Le abilità che questo personaggio non conosce ancora e le macro che non ha vengono saltate.",
    ["Accountweite Einstellungen"] = "Impostazioni dell'account",
    ["Fenster nicht gefunden"] = "Finestra non trovata",
    ["(nicht gesetzt)"] = "(non impostato)",
    ["WoW-Optionen (accountweit)"] = "Opzioni di WoW (tutto l'account)",
    ["Minimap-Icons"] = "Pulsanti della minimappa",
    ["(kein Makro)"] = "(nessuna macro)",
    ["(leer)"] = "(vuoto)",
    ["Makro-Text:"] = "Testo della macro:",
    ["In der Vorlage:"] = "Nel modello:",
    ["Jetzt:"] = "Ora:",
    ["Vorlage:"] = "Modello:",
    ["Dieser Char:"] = "Questo personaggio:",
    ["Abgewählt: wird nie synchronisiert bzw. nicht verfolgt."] = "Escluso: mai sincronizzato né monitorato.",
    ["Haken setzen: wieder einbeziehen."] = "Spunta per includerlo di nuovo.",
    ["|cffffd100Vorher:|r %s"] = "|cffffd100Prima:|r %s",
    ["|cffffd100Jetzt:|r %s"] = "|cffffd100Ora:|r %s",
    ["Zurücksetzen = alten Wert wiederherstellen. Übernehmen = neuen Wert als Stand merken."] = "Ripristina = rimette il valore vecchio. Accetta = memorizza il nuovo valore come stato.",
    ["Rechtsklick: diese Einstellung nie verfolgen."] = "Clic destro: non seguire mai questa impostazione.",
    ["Intern: %s"] = "Interno: %s",
    ["Macht nur diese Änderung der letzten Übernahme rückgängig."] = "Annulla solo questa modifica dell'ultima applicazione.",
    ["|cffffd100Vor der Übernahme:|r %s"] = "|cffffd100Prima dell'applicazione:|r %s",
    ["Vor der Übernahme:"] = "Prima dell'applicazione:",
    ["Seit dem Speichern der Vorlage geändert. Mit „Vorlage aktualisieren“ geht diese Änderung an die anderen Chars."] = "Modificato dopo il salvataggio del modello. “Aggiorna modello” invia questa modifica agli altri personaggi.",
    ["|cffffd100In der Vorlage:|r %s"] = "|cffffd100Nel modello:|r %s",
    ["|cffffd100Vorlage (%s):|r %s"] = "|cffffd100Modello (%s):|r %s",
    ["|cffffd100Dieser Char:|r %s"] = "|cffffd100Questo personaggio:|r %s",
    ["Beim Übernehmen: %s"] = "Applicando: %s",
    ["Nicht möglich: %s"] = "Non possibile: %s",
    ["Wird nur übernommen, wenn du den Haken ausdrücklich setzt."] = "Applicato solo se lo spunti esplicitamente.",
    ["Wird nach einem Neuladen der Oberfläche vollständig aktiv."] = "Ha pieno effetto dopo aver ricaricato l'interfaccia.",
    ["Haken entfernen = diese Einstellung nie synchronisieren (gilt für alle Chars)."] = "Togli la spunta = non sincronizzare mai questa impostazione (per tutti i personaggi).",
    ["Alles in diesem Abschnitt anhaken oder abwählen."] = "Spunta o deseleziona tutto in questa sezione.",
    ["Vorlage für %s"] = "Modello per %s",
    ["Allgemeine Vorlage"] = "Modello generale",
    ["noch keine"] = "ancora nessuno",
    ["(dieser Char)"] = "(questo personaggio)",
    ["%d.%m.%Y um %H:%M"] = "%d/%m/%Y alle %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync – copia le impostazioni su tutti i personaggi",
    ["Als allgemeine Vorlage speichern"] = "Salva come modello generale",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "Salva tutte le impostazioni di questo personaggio così come sono: il modello generale e il modello della sua classe (se lo fornisce questo personaggio). Le impostazioni dell'account restano invariate: accettale con i pulsanti in basso a destra.",
    ["Als Klassen-Vorlage speichern"] = "Salva come modello di classe",
    ["Klassen-Vorlage"] = "Modello di classe",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "Salva macro e barre delle azioni di questo personaggio come modello per tutti i personaggi della classe %s.",
    ["Allgemeiner Vorlage-Char"] = "Personaggio modello generale",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "Questo personaggio fornisce il modello generale. Con “Aggiorna modello automaticamente” viene salvato da solo, altrimenti con il pulsante o uno per uno con “Nel modello”.",
    ["Vorlage-Char seiner Klasse"] = "Personaggio modello della sua classe",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "Questo personaggio fornisce macro e barre delle azioni della sua classe. Con “Aggiorna modello automaticamente” questo modello viene salvato da solo.",
    ["Ohne Nachfrage übernehmen"] = "Applica senza chiedere",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "I nuovi modelli vengono applicati subito all'accesso, senza aprire questa finestra per il controllo.",
    ["Vorlage automatisch aktualisieren"] = "Aggiorna modello automaticamente",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "I personaggi modello salvano il loro modello una volta al minuto e alla disconnessione, se qualcosa è cambiato. Predefinito: disattivato.",
    ["Minimap-Icon anzeigen"] = "Mostra pulsante sulla minimappa",
    ["Zeigt das CharSync-Icon an der Minimap. Ein Klick darauf öffnet dieses Fenster."] = "Mostra il pulsante di CharSync sulla minimappa. Un clic apre questa finestra.",
    ["Bereiche"] = "Sezioni",
    ["(gleiche Klasse)"] = "(stessa classe)",
    ["Verfolgt Einstellungen, die für alle Chars gelten (accountweite Addon-Einstellungen, accountweite WoW-Optionen): Bei jedem Einloggen merkt sich CharSync den Stand, danach erscheint hier jede Änderung mit vorherigem Wert – einzeln übernehmen oder zurücksetzen, ausgewählte oder alle. Standard: aus."] = "Segue le impostazioni valide per tutti i personaggi (impostazioni degli addon e opzioni di WoW dell'account): a ogni accesso CharSync memorizza lo stato attuale; poi ogni modifica compare qui con il valore precedente – accettala o ripristinala una per una, le selezionate o tutte. Predefinito: disattivato.",
    ["Abgewählte Einstellungen"] = "Impostazioni escluse",
    ["Zeigt am Ende der Liste die Einstellungen, die du abgewählt hast (nie synchronisieren, nie verfolgen). Ein Haken dort holt sie zurück."] = "Mostra in fondo all'elenco le impostazioni che hai escluso (mai sincronizzare, mai monitorare). Spuntarle lì le ripristina.",
    ["Vergleich: dieser Char » Vorlage"] = "Confronto: questo personaggio » modello",
    ["Alle anhaken"] = "Spunta tutto",
    ["Hakt alles in der Liste an. Abgewählte Einstellungen bleiben abgewählt."] = "Spunta tutto nell'elenco. Le impostazioni escluse restano escluse.",
    ["Keine"] = "Nessuno",
    ["Entfernt alle Haken in der Liste."] = "Toglie tutte le spunte dall'elenco.",
    ["Angehakte übernehmen"] = "Applica selezionati",
    ["Übernimmt alles Angehakte: Abweichungen zur Vorlage werden übernommen, accountweite Einstellungen werden der neue Stand, Änderungen seit der Vorlage gehen in die Vorlage."] = "Applica tutto ciò che è spuntato: le differenze con il modello vengono applicate, le impostazioni dell'account diventano il nuovo stato, le modifiche dal modello vanno nel modello.",
    ["Alle übernehmen"] = "Applica tutto",
    ["Übernimmt alles in der Liste: Abweichungen zur Vorlage (außer nie zu synchronisierenden), accountweite Einstellungen als neuen Stand, Änderungen seit der Vorlage in die Vorlage."] = "Applica tutto l'elenco: differenze con il modello (tranne quelle da non sincronizzare mai), impostazioni dell'account come nuovo stato, modifiche dal modello nel modello.",
    ["Alle zurücksetzen"] = "Ripristina tutto",
    ["Setzt alle zurücksetzbaren Änderungen in der Liste zurück: Änderungen seit der Vorlage, die letzte Übernahme und accountweite Einstellungen."] = "Ripristina tutte le modifiche ripristinabili dell'elenco: modifiche dal modello, ultima applicazione e impostazioni dell'account.",
    ["Ausgewählte zurücksetzen"] = "Ripristina selezionati",
    ["Setzt nur die angehakten Änderungen zurück."] = "Ripristina solo le modifiche spuntate.",
    ["Schließt das Fenster. Beim nächsten Login wirst du wieder gefragt."] = "Chiude la finestra. Ti verrà chiesto di nuovo al prossimo accesso.",
    ["Diesmal nichts"] = "Non stavolta",
    ["Übernimmt nichts und fragt erst wieder, wenn eine neuere Vorlage gespeichert wird."] = "Non applica nulla e chiede di nuovo solo quando viene salvato un modello più recente.",
    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "Nuovo modello da %s: controlla cosa applicare.",
    ["Einstellungen dieses Chars (%s, %s)"] = "Impostazioni di questo personaggio (%s, %s)",
    ["Als Vorlage für %s speichern"] = "Salva come modello per %s",
    ["Vorlage-Char für %s"] = "Personaggio modello per %s",
    ["Letzte Übernahme vom %s"] = "Ultima applicazione del %s",
    ["Alles rückgängig"] = "Annulla tutto",
    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "Annulla tutte le modifiche dell'ultima applicazione ancora presenti.",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Prima dell'applicazione:|r |cff90ff90%s|r   »   |cffffd100Ora:|r |cffff9090%s|r",
    ["Rückgängig"] = "Annulla",
    ["(Klassen-Vorlage)"] = "(modello di classe)",
    ["(seit der Vorlage geändert)"] = "(modificato dopo il modello)",
    ["In Vorlage"] = "Nel modello",
    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "Porta solo questa modifica nel modello. Gli altri personaggi la vedranno al prossimo accesso.",
    ["Zurücksetzen"] = "Ripristina",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "Riporta solo questa impostazione di questo personaggio allo stato del modello.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100Nel modello:|r %s   »   |cffffd100Ora:|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100Modello:|r |cff90ff90%s|r   »   |cffffd100Questo personaggio:|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(dall'accesso del %s)",
    ["Wird gelesen …"] = "Lettura in corso…",
    ["Keine Änderungen seit dem Einloggen."] = "Nessuna modifica dall'accesso.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Prima:|r |cff90ff90%s|r   »   |cffffd100Ora:|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "Vale per tutti i personaggi. Clic destro: non seguire mai.",
    ["Übernehmen"] = "Accetta",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "Memorizza il nuovo valore come stato; la riga scompare.",
    ["Stellt den vorherigen Wert wieder her."] = "Rimette il valore precedente.",
    ["Abgewählt (%d)"] = "Esclusi (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "Nessun modello ancora salvato. Accedi con il personaggio le cui impostazioni devono valere per tutti e clicca a sinistra su “Salva come modello generale”. Per macro e barre delle azioni salva un modello di classe per ogni classe.",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "Nessuna differenza: questo personaggio corrisponde ai modelli.",
    ["%d Abweichungen, %d angehakt"] = "%d differenze, %d spuntate",
    ["%d Änderungen seit der Vorlage"] = "%d modifiche dopo il modello",
    ["%d accountweit"] = "%d dell'account",
    ["%d Einstellung(en) abgewählt"] = "%d impostazione/i deselezionata/e",
    ["%d Änderung(en) übernommen."] = "%d modifica/he accettata/e.",
    ["Speichert die Einstellungen des aktuellen Chars als Vorlage und überträgt sie auf die anderen Chars, sobald diese sich einloggen. Makros und Aktionsleisten gehen nur an Chars derselben Klasse. Vor dem Übernehmen siehst du für jede Einstellung vorher und nachher und kannst sie einzeln abwählen.\n\nBefehle: /charsync (Fenster), /charsync save (allgemeine Vorlage), /charsync saveclass (Klassen-Vorlage), /charsync apply (übernehmen)"] = "Salva le impostazioni del personaggio attuale come modello e le copia sugli altri tuoi personaggi quando accedono. Macro e barre delle azioni vanno solo ai personaggi della stessa classe. Prima di applicare vedi il prima e il dopo di ogni impostazione e puoi togliere la spunta a ciascuna.\n\nComandi: /charsync (finestra), /charsync save (modello generale), /charsync saveclass (modello di classe), /charsync apply (applica)",
    ["CharSync-Fenster öffnen"] = "Apri la finestra di CharSync",
    ["Neue Vorlage zum Prüfen"] = "Nuovo modello da controllare",
    ["Klicken: Fenster öffnen"] = "Clic: apri la finestra",
    ["Ziehen: Icon verschieben"] = "Trascina: sposta il pulsante",
    ["Minimap-Icon zurückgesetzt."] = "Pulsante della minimappa ripristinato.",
    ["Hauptleiste"] = "Barra principale",
    ["Hauptleiste Seite 2"] = "Barra principale pagina 2",
    ["Leiste rechts"] = "Barra destra",
    ["Leiste rechts 2"] = "Barra destra 2",
    ["Leiste unten rechts"] = "Barra in basso a destra",
    ["Leiste unten links"] = "Barra in basso a sinistra",
    ["Haltungs-/Gestaltleiste 1"] = "Barra delle posture/forme 1",
    ["Haltungs-/Gestaltleiste 2"] = "Barra delle posture/forme 2",
    ["Haltungs-/Gestaltleiste 3"] = "Barra delle posture/forme 3",
    ["Haltungs-/Gestaltleiste 4"] = "Barra delle posture/forme 4",
    ["Leiste"] = "Barra",
}
T.ruRU = {
