    ["|cffffd100Jetzt:|r %s"] = "|cffffd100Сейчас:|r %s",
    ["Zurücksetzen = alten Wert wiederherstellen. Übernehmen = neuen Wert als Stand merken."] = "Сбросить = вернуть старое значение. Принять = запомнить новое значение как состояние.",
    ["Rechtsklick: diese Einstellung nie verfolgen."] = "Правый щелчок: никогда не отслеживать эту настройку.",
    ["Intern: %s"] = "Внутреннее имя: %s",
