    ["Seit dem Speichern der Vorlage geändert. Mit „Vorlage aktualisieren“ geht diese Änderung an die anderen Chars."] = "Изменено после сохранения шаблона. «Обновить шаблон» передаст это изменение другим персонажам.",
    ["|cffffd100In der Vorlage:|r %s"] = "|cffffd100В шаблоне:|r %s",
    ["|cffffd100Vorlage (%s):|r %s"] = "|cffffd100Шаблон (%s):|r %s",
    ["|cffffd100Dieser Char:|r %s"] = "|cffffd100Этот персонаж:|r %s",
