    ["Wird nach einem Neuladen der Oberfläche vollständig aktiv."] = "Полностью вступает в силу после перезагрузки интерфейса.",
    ["Haken entfernen = diese Einstellung nie synchronisieren (gilt für alle Chars)."] = "Снять отметку = никогда не синхронизировать эту настройку (для всех персонажей).",
    ["Alles in diesem Abschnitt anhaken oder abwählen."] = "Отметить или снять отметку со всего в этом разделе.",
    ["Vorlage für %s"] = "Шаблон для класса %s",
    ["Allgemeine Vorlage"] = "Общий шаблон",
    ["noch keine"] = "пока нет",
    ["(dieser Char)"] = "(этот персонаж)",
    ["%d.%m.%Y um %H:%M"] = "%d.%m.%Y в %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync – перенос настроек на всех персонажей",
    ["Als allgemeine Vorlage speichern"] = "Сохранить как общий шаблон",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "Сохраняет все настройки этого персонажа как есть: общий шаблон и шаблон его класса (если его задаёт этот персонаж). Настройки аккаунта не затрагиваются – их принимают кнопками справа внизу.",
    ["Als Klassen-Vorlage speichern"] = "Сохранить как шаблон класса",
    ["Klassen-Vorlage"] = "Шаблон класса",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "Сохраняет макросы и панели команд этого персонажа как шаблон для всех персонажей класса %s.",
    ["Allgemeiner Vorlage-Char"] = "Персонаж общего шаблона",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "Этот персонаж задаёт общий шаблон. С «Обновлять шаблон автоматически» он сохраняется сам, иначе — кнопкой или по одному через «В шаблон».",
    ["Vorlage-Char seiner Klasse"] = "Персонаж-шаблон своего класса",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "Этот персонаж задаёт макросы и панели команд своего класса. С «Обновлять шаблон автоматически» этот шаблон сохраняется сам.",
    ["Ohne Nachfrage übernehmen"] = "Применять без вопросов",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "Новые шаблоны применяются сразу при входе, без открытия этого окна для проверки.",
    ["Vorlage automatisch aktualisieren"] = "Обновлять шаблон автоматически",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "Персонажи-шаблоны сохраняют свой шаблон раз в минуту и при выходе, если что-то изменилось. По умолчанию выключено.",
    ["Minimap-Icon anzeigen"] = "Кнопка у мини-карты",
    ["Zeigt das CharSync-Icon an der Minimap. Ein Klick darauf öffnet dieses Fenster."] = "Показывает кнопку CharSync у мини-карты. Щелчок открывает это окно.",
    ["Bereiche"] = "Разделы",
    ["(gleiche Klasse)"] = "(тот же класс)",
    ["Verfolgt Einstellungen, die für alle Chars gelten (accountweite Addon-Einstellungen, accountweite WoW-Optionen): Bei jedem Einloggen merkt sich CharSync den Stand, danach erscheint hier jede Änderung mit vorherigem Wert – einzeln übernehmen oder zurücksetzen, ausgewählte oder alle. Standard: aus."] = "Отслеживает настройки, действующие для всех персонажей (настройки модификаций и WoW для всей учётной записи): при каждом входе CharSync запоминает текущее состояние, затем здесь появляется каждое изменение с прежним значением – принимайте или сбрасывайте по одному, отмеченные или все. По умолчанию выключено.",
    ["Abgewählte Einstellungen"] = "Исключённые настройки",
    ["Zeigt am Ende der Liste die Einstellungen, die du abgewählt hast (nie synchronisieren, nie verfolgen). Ein Haken dort holt sie zurück."] = "Показывает в конце списка исключённые настройки (не синхронизировать, не отслеживать). Отметка там возвращает их.",
    ["Vergleich: dieser Char » Vorlage"] = "Сравнение: этот персонаж » шаблон",
    ["Alle anhaken"] = "Отметить все",
    ["Hakt alles in der Liste an. Abgewählte Einstellungen bleiben abgewählt."] = "Отмечает всё в списке. Исключённые настройки остаются исключёнными.",
    ["Keine"] = "Ничего",
    ["Entfernt alle Haken in der Liste."] = "Снимает все отметки в списке.",
    ["Angehakte übernehmen"] = "Применить отмеченное",
    ["Übernimmt alles Angehakte: Abweichungen zur Vorlage werden übernommen, accountweite Einstellungen werden der neue Stand, Änderungen seit der Vorlage gehen in die Vorlage."] = "Применяет всё отмеченное: отличия от шаблона применяются, настройки учётной записи становятся новым состоянием, изменения после шаблона попадают в шаблон.",
    ["Alle übernehmen"] = "Применить всё",
    ["Übernimmt alles in der Liste: Abweichungen zur Vorlage (außer nie zu synchronisierenden), accountweite Einstellungen als neuen Stand, Änderungen seit der Vorlage in die Vorlage."] = "Применяет всё из списка: отличия от шаблона (кроме тех, что никогда не синхронизируются), настройки учётной записи как новое состояние, изменения после шаблона – в шаблон.",
    ["Alle zurücksetzen"] = "Сбросить всё",
    ["Setzt alle zurücksetzbaren Änderungen in der Liste zurück: Änderungen seit der Vorlage, die letzte Übernahme und accountweite Einstellungen."] = "Сбрасывает все изменения в списке, которые можно сбросить: изменения после шаблона, последнее применение и настройки учётной записи.",
    ["Ausgewählte zurücksetzen"] = "Сбросить отмеченные",
    ["Setzt nur die angehakten Änderungen zurück."] = "Сбрасывает только отмеченные изменения.",
    ["Schließt das Fenster. Beim nächsten Login wirst du wieder gefragt."] = "Закрывает окно. При следующем входе вас спросят снова.",
    ["Diesmal nichts"] = "Не сейчас",
    ["Übernimmt nichts und fragt erst wieder, wenn eine neuere Vorlage gespeichert wird."] = "Ничего не применяет и спросит снова, только когда будет сохранён новый шаблон.",
    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "Новый шаблон от %s – проверьте, что следует применить.",
    ["Einstellungen dieses Chars (%s, %s)"] = "Настройки этого персонажа (%s, %s)",
    ["Als Vorlage für %s speichern"] = "Сохранить как шаблон для класса %s",
    ["Vorlage-Char für %s"] = "Персонаж-шаблон для класса %s",
    ["Letzte Übernahme vom %s"] = "Последнее применение: %s",
    ["Alles rückgängig"] = "Отменить всё",
    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "Отменяет все ещё действующие изменения последнего применения.",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100До применения:|r |cff90ff90%s|r   »   |cffffd100Сейчас:|r |cffff9090%s|r",
    ["Rückgängig"] = "Отменить",
    ["(Klassen-Vorlage)"] = "(шаблон класса)",
    ["(seit der Vorlage geändert)"] = "(изменено после шаблона)",
    ["In Vorlage"] = "В шаблон",
    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "Переносит в шаблон только это изменение. Другие персонажи увидят его при следующем входе.",
    ["Zurücksetzen"] = "Сбросить",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "Возвращает только эту настройку этого персонажа к состоянию шаблона.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100В шаблоне:|r %s   »   |cffffd100Сейчас:|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100Шаблон:|r |cff90ff90%s|r   »   |cffffd100Этот персонаж:|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(с момента входа: %s)",
    ["Wird gelesen …"] = "Чтение…",
    ["Keine Änderungen seit dem Einloggen."] = "Нет изменений с момента входа.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100Было:|r |cff90ff90%s|r   »   |cffffd100Сейчас:|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "Действует для всех персонажей. Правый щелчок: не отслеживать.",
    ["Übernehmen"] = "Принять",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "Запоминает новое значение как состояние; строка исчезает.",
    ["Stellt den vorherigen Wert wieder her."] = "Возвращает прежнее значение.",
    ["Abgewählt (%d)"] = "Исключено (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "Шаблон ещё не сохранён. Войдите в игру персонажем, чьи настройки должны действовать для всех, и нажмите слева «Сохранить как общий шаблон». Для макросов и панелей команд сохраните по одному шаблону класса для каждого класса.",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "Различий нет – этот персонаж соответствует шаблонам.",
    ["%d Abweichungen, %d angehakt"] = "Различий: %d, отмечено: %d",
    ["%d Änderungen seit der Vorlage"] = "Изменений после шаблона: %d",
    ["%d accountweit"] = "Для учётной записи: %d",
    ["%d Einstellung(en) abgewählt"] = "Снято отметок: %d",
    ["%d Änderung(en) übernommen."] = "Принято изменений: %d.",
    ["Speichert die Einstellungen des aktuellen Chars als Vorlage und überträgt sie auf die anderen Chars, sobald diese sich einloggen. Makros und Aktionsleisten gehen nur an Chars derselben Klasse. Vor dem Übernehmen siehst du für jede Einstellung vorher und nachher und kannst sie einzeln abwählen.\n\nBefehle: /charsync (Fenster), /charsync save (allgemeine Vorlage), /charsync saveclass (Klassen-Vorlage), /charsync apply (übernehmen)"] = "Сохраняет настройки текущего персонажа как шаблон и переносит их на других ваших персонажей при их входе в игру. Макросы и панели команд переносятся только на персонажей того же класса. Перед применением вы видите для каждой настройки значение до и после и можете снять отметку с любой из них.\n\nКоманды: /charsync (окно), /charsync save (общий шаблон), /charsync saveclass (шаблон класса), /charsync apply (применить)",
    ["CharSync-Fenster öffnen"] = "Открыть окно CharSync",
    ["Neue Vorlage zum Prüfen"] = "Новый шаблон для проверки",
    ["Klicken: Fenster öffnen"] = "Щелчок: открыть окно",
    ["Ziehen: Icon verschieben"] = "Перетаскивание: переместить кнопку",
    ["Minimap-Icon zurückgesetzt."] = "Кнопка у миникарты сброшена.",
    ["Hauptleiste"] = "Основная панель",
    ["Hauptleiste Seite 2"] = "Основная панель, стр. 2",
    ["Leiste rechts"] = "Правая панель",
    ["Leiste rechts 2"] = "Правая панель 2",
    ["Leiste unten rechts"] = "Нижняя правая панель",
    ["Leiste unten links"] = "Нижняя левая панель",
    ["Haltungs-/Gestaltleiste 1"] = "Панель стоек/облика 1",
    ["Haltungs-/Gestaltleiste 2"] = "Панель стоек/облика 2",
    ["Haltungs-/Gestaltleiste 3"] = "Панель стоек/облика 3",
    ["Haltungs-/Gestaltleiste 4"] = "Панель стоек/облика 4",
    ["Leiste"] = "Панель",
}
T.koKR = {
    ["Standard"] = "기본값",
    ["An"] = "켜짐",
    ["Aus"] = "꺼짐",
    ["keine"] = "없음",
    ["Auswahl %s"] = "선택 %s",
    ["Liste"] = "목록",
    ["WoW-Einstellung, die pro Charakter gespeichert wird (CVar „%s“). Zu ihr ist keine Beschreibung hinterlegt."] = "캐릭터별로 저장되는 WoW 설정입니다(CVar “%s”). 이 설정에 대한 설명이 없습니다.",
    ["blendet ein: %s"] = "표시: %s",
    ["blendet aus: %s"] = "숨김: %s",
    ["schaltet ein"] = "켭니다",
    ["schaltet aus"] = "끕니다",
    ["stellt „%s“ auf „%s“ um"] = "“%s”에서 “%s”(으)로 바꿉니다",
    ["Zusätzliche Aktionsleisten"] = "추가 행동 단축바",
    ["Blendet die zusätzlichen Aktionsleisten ein oder aus (Optionen > Aktionsleisten). Die Belegung der Leisten bleibt, wie sie ist – sie liegt auf dem Server."] = "추가 행동 단축바를 표시하거나 숨깁니다(설정 > 행동 단축바). 단축바에 놓인 내용은 그대로 유지됩니다 – 서버에 저장되기 때문입니다.",
    ["Persönliche Ressourcenanzeige"] = "개인 자원 표시",
    ["Zeigt unter deinem Charakter eine eigene Leiste mit Gesundheit und Mana/Energie (eigene Namensplakette)."] = "캐릭터 아래에 생명력과 마나/기력 바를 표시합니다(자신의 이름표).",
    ["Questlevel anzeigen"] = "퀘스트 레벨 표시",
    ["Zeigt im Questlog und im Questtracker das Level jeder Quest vor dem Namen an."] = "퀘스트 목록과 퀘스트 추적기에서 각 퀘스트 이름 앞에 레벨을 표시합니다.",
    ["Raidframes: Klassenfarben"] = "공격대 창: 직업 색상",
    ["Färbt die Gesundheitsleisten in Gruppen- und Schlachtzugsfenstern in der Klassenfarbe statt grün."] = "파티 및 공격대 창의 생명력 바를 녹색 대신 직업 색상으로 표시합니다.",
    ["Raidframes: Kraftleisten"] = "공격대 창: 자원 바",
    ["Zeigt in Gruppen- und Schlachtzugsfenstern unter der Gesundheit eine Leiste für Mana, Wut oder Energie."] = "파티 및 공격대 창에서 생명력 아래에 마나, 분노 또는 기력 바를 표시합니다.",
    ["Raidframes: nur entfernbare Schwächungen"] = "공격대 창: 해제 가능한 약화 효과만",
    ["Zeigt in den Raidframes nur Schwächungen, die du selbst entfernen kannst."] = "공격대 창에 직접 해제할 수 있는 약화 효과만 표시합니다.",
    ["Raidframes: Gesundheitstext"] = "공격대 창: 생명력 문자",
    ["Welcher Text in den Raidframes auf der Gesundheitsleiste steht (keiner, Gesundheit, verlorene Gesundheit, Prozent)."] = "공격대 창의 생명력 바에 표시할 문자입니다(없음, 생명력, 잃은 생명력, 백분율).",
    ["Raidframes: Begleiter anzeigen"] = "공격대 창: 소환수 표시",
    ["Zeigt die Begleiter der Gruppenmitglieder als eigene Raidframes."] = "파티원의 소환수를 별도의 공격대 창으로 표시합니다.",
    ["Raidframes: Haupttank und -assistent"] = "공격대 창: 방어 전담 및 지원 공격 전담",
    ["Zeigt Haupttank und Hauptassistent als eigene Raidframes."] = "방어 전담과 지원 공격 전담을 별도의 공격대 창으로 표시합니다.",
    ["Gruppenfenster im Raid-Stil"] = "공격대 스타일 파티 창",
    ["Nutzt für die Gruppe dieselben kompakten Fenster wie im Schlachtzug."] = "파티에도 공격대와 같은 간소한 창을 사용합니다.",
    ["Karte beim Laufen ausblenden"] = "이동 중 지도 흐리게",
    ["Macht die geöffnete Weltkarte durchsichtig, während du dich bewegst."] = "이동하는 동안 열려 있는 세계 지도를 투명하게 만듭니다.",
    ["Kleine Weltkarte"] = "작은 세계 지도",
    ["Öffnet die Weltkarte als kleines Fenster statt als großes Vollbild."] = "세계 지도를 전체 화면 대신 작은 창으로 엽니다.",
    ["Minimap-Verfolgung"] = "미니맵 추적",
    ["Was die Minimap anzeigt, z. B. Briefkasten, Lehrer, Händler, Gasthäuser (Lupe an der Minimap). Kräuter- und Erzsuche hängen vom Beruf ab und bleiben dabei unverändert."] = "미니맵에 표시할 대상입니다. 예: 우체통, 기술 전문가, 상인, 여관(미니맵의 돋보기). 약초 찾기와 광물 찾기는 전문 기술에 따라 다르므로 변경되지 않습니다.",
    ["Minimap-Zoom (draußen)"] = "미니맵 확대(야외)",
