    ["(dieser Char)"] = "(이 캐릭터)",
    ["%d.%m.%Y um %H:%M"] = "%Y년 %m월 %d일 %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync – 모든 캐릭터에 설정 복사",
    ["Als allgemeine Vorlage speichern"] = "공통 템플릿으로 저장",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "이 캐릭터의 모든 설정을 현재 상태 그대로 저장합니다: 일반 템플릿과 직업 템플릿(이 캐릭터가 제공하는 경우). 계정 전체 설정은 변경되지 않으며, 오른쪽 아래 버튼으로 적용합니다.",
    ["Als Klassen-Vorlage speichern"] = "직업 템플릿으로 저장",
    ["Klassen-Vorlage"] = "직업 템플릿",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "이 캐릭터의 매크로와 행동 단축바를 %s 직업의 모든 캐릭터용 템플릿으로 저장합니다.",
    ["Allgemeiner Vorlage-Char"] = "공통 템플릿 캐릭터",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "이 캐릭터가 공통 템플릿을 제공합니다. “템플릿 자동 업데이트”를 켜면 자동으로 저장되고, 아니면 버튼이나 “템플릿에 반영”으로 하나씩 저장합니다.",
    ["Vorlage-Char seiner Klasse"] = "직업 템플릿 캐릭터",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "이 캐릭터가 직업의 매크로와 행동 단축바를 제공합니다. “템플릿 자동 업데이트”를 켜면 이 템플릿이 자동으로 저장됩니다.",
    ["Ohne Nachfrage übernehmen"] = "묻지 않고 적용",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "새 템플릿을 접속 즉시 적용하며, 확인용 창을 열지 않습니다.",
    ["Vorlage automatisch aktualisieren"] = "템플릿 자동 업데이트",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "템플릿 캐릭터는 무언가 바뀌었을 때 1분마다, 그리고 접속 종료 시 템플릿을 저장합니다. 기본값: 꺼짐.",
    ["Minimap-Icon anzeigen"] = "미니맵 버튼 표시",
