    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "%s의 새 템플릿 – 적용할 항목을 확인하세요.",
    ["Einstellungen dieses Chars (%s, %s)"] = "이 캐릭터의 설정(%s, %s)",
