    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "이 변경만 템플릿에 반영합니다. 다른 캐릭터는 다음 접속 시 보게 됩니다.",
    ["Zurücksetzen"] = "되돌리기",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "이 캐릭터의 이 설정만 템플릿 상태로 되돌립니다.",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100템플릿:|r %s   »   |cffffd100현재:|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100템플릿:|r |cff90ff90%s|r   »   |cffffd100이 캐릭터:|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "(%s 접속 이후)",
    ["Wird gelesen …"] = "읽는 중…",
    ["Keine Änderungen seit dem Einloggen."] = "접속 이후 변경 사항이 없습니다.",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100이전:|r |cff90ff90%s|r   »   |cffffd100현재:|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "모든 캐릭터에 적용됩니다. 오른쪽 클릭: 추적하지 않음.",
    ["Übernehmen"] = "반영",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "새 값을 기준 상태로 기억합니다. 줄이 사라집니다.",
    ["Stellt den vorherigen Wert wieder her."] = "이전 값을 복원합니다.",
    ["Abgewählt (%d)"] = "제외됨 (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "아직 저장된 템플릿이 없습니다. 모든 캐릭터에 적용할 설정을 가진 캐릭터로 접속한 뒤 왼쪽의 “공통 템플릿으로 저장”을 클릭하세요. 매크로와 행동 단축바는 직업마다 직업 템플릿을 하나씩 저장하세요.",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "차이 없음 – 이 캐릭터는 템플릿과 일치합니다.",
    ["%d Abweichungen, %d angehakt"] = "차이 %d개, 체크 %d개",
