    ["Leiste rechts 2"] = "오른쪽 단축바 2",
    ["Leiste unten rechts"] = "오른쪽 하단 단축바",
    ["Leiste unten links"] = "왼쪽 하단 단축바",
    ["Haltungs-/Gestaltleiste 1"] = "태세/변신 단축바 1",
    ["Haltungs-/Gestaltleiste 2"] = "태세/변신 단축바 2",
    ["Haltungs-/Gestaltleiste 3"] = "태세/변신 단축바 3",
