    ["Vorlage-Char seiner Klasse"] = "本职业的模板角色",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "此角色为其职业提供宏和动作条。开启“自动更新模板”后，此模板会自动保存。",
    ["Ohne Nachfrage übernehmen"] = "无需确认直接应用",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "登录时立即应用新模板，不会打开此窗口供你检查。",
    ["Vorlage automatisch aktualisieren"] = "自动更新模板",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "模板角色在有变化时，每分钟一次并在登出时保存其模板。默认：关闭。",
    ["Minimap-Icon anzeigen"] = "显示小地图按钮",
