    ["Die Vorlage enthält keine Aktionen. Speichere sie beim Vorlage-Char neu."] = "範本中沒有任何動作。請在範本角色上重新儲存。",
    ["Diese Fähigkeit kennt dieser Char (noch) nicht."] = "此角色（還）不會這個技能。",
    ["Das Makro gibt es bei diesem Char nicht."] = "此角色沒有這個巨集。",
    ["Diese Art von Aktion kann nicht übertragen werden."] = "這種動作無法轉移。",
    ["leert diesen Platz („%s“ fällt weg)"] = "清空此位置（移除「%s」）",
    ["legt „%s“ auf diesen Platz"] = "將「%s」放到此位置",
    ["Leert diesen Platz, weil er beim Vorlage-Char frei ist."] = "清空此欄位，因為範本角色的這個欄位是空的。",
    ["Legt „%s“ auf diesen Platz der Aktionsleiste, wie beim Vorlage-Char."] = "如同範本角色，將「%s」放到快捷列的此欄位。",
    ["konnte „%s“ nicht aufnehmen"] = "無法拿起「%s」",
    ["Interface-Optionen"] = "介面選項",
    ["Optionen, die WoW pro Charakter speichert: zusätzliche Aktionsleisten, persönliche Ressourcenanzeige, Questlevel, Raidframe-Optionen, Weltkarte, Minimap. Grafik, Sound und die meisten anderen Optionen gelten ohnehin für alle Chars."] = "WoW依角色儲存的選項：額外快捷列、個人資源顯示、任務等級、團隊框架選項、世界地圖、小地圖。圖形、音效與其他大部分選項本來就適用於所有角色。",
    ["Chatfenster & Farben"] = "聊天視窗與顏色",
    ["Chat-Tabs (Name, Schriftgröße, Hintergrund), welche Nachrichtenarten und Kanäle darin erscheinen und die Farben der Chat-Arten. Fehlende Kanäle werden betreten."] = "聊天分頁（名稱、字型大小、背景）、其中顯示哪些訊息類型與頻道，以及聊天類型的顏色。會自動加入缺少的頻道。",
    ["Edit-Mode-Layout"] = "編輯模式版面配置",
    ["Welches Edit-Mode-Layout aktiv ist. Die Layouts selbst sind accountweit, nur die Auswahl ist pro Char."] = "目前使用哪個編輯模式版面配置。版面配置本身是帳號通用的，只有選擇是依角色儲存的。",
    ["Tastenbelegung"] = "按鍵設定",
    ["Alle Tastenbelegungen. Nutzen alle Chars die accountweite Belegung, gibt es hier keine Abweichungen – wichtig nur für Chars mit charakterspezifischer Belegung."] = "所有按鍵設定。如果所有角色都使用帳號通用的按鍵設定，這裡就不會有差異——只對使用角色專用按鍵設定的角色有意義。",
    ["Addon-Auswahl"] = "已啟用的插件",
    ["Welche Addons bei diesem Char aktiviert sind (Addon-Menü am Charakterauswahl-Bildschirm). Wird nach einem Neuladen aktiv."] = "此角色啟用了哪些插件（角色選擇畫面上的插件選單）。重新載入後生效。",
    ["Addon-Profile (Ace3)"] = "插件設定檔（Ace3）",
    ["Welches Profil Addons nutzen, die ihre Einstellungen über die Bibliothek Ace3 speichern. Mit dem Profil des Vorlage-Chars teilen sich beide alle Einstellungen dieses Addons, auch Fensterpositionen und das Minimap-Icon."] = "透過 Ace3 函式庫儲存設定的插件所使用的設定檔。使用範本角色的設定檔後，兩者共用該插件的全部設定，包括視窗位置與小地圖按鈕。",
    ["Fensterpositionen"] = "視窗位置",
    ["Wo verschiebbare Fenster stehen, deren Position WoW pro Char merkt (Fenster von WoW und von Addons). Positionen, die ein Addon selbst accountweit speichert, gelten ohnehin für alle Chars."] = "WoW 依角色記住位置的可移動視窗所在的位置（WoW 視窗與插件視窗）。插件自行依帳號儲存的位置原本就對所有角色生效。",
    ["Makros"] = "巨集",
    ["Charakterspezifische Makros – nur zwischen Chars derselben Klasse. Fehlende Makros werden angelegt, abweichende angepasst. Makros, die es beim Vorlage-Char nicht gibt, werden nur gelöscht, wenn du sie ausdrücklich anhakst."] = "角色專用巨集——僅限同職業角色之間。缺少的巨集會被建立，不同的巨集會被更新。範本角色沒有的巨集，只有在你明確勾選後才會刪除。",
    ["Aktionsleisten"] = "快捷列",
    ["Was auf den Aktionsleisten liegt – nur zwischen Chars derselben Klasse. Fähigkeiten, die dieser Char noch nicht kennt, und Makros, die es hier nicht gibt, werden übersprungen."] = "快捷列上的內容——僅限同職業角色之間。此角色尚未學會的技能與這裡沒有的巨集會被略過。",
    ["Accountweite Einstellungen"] = "帳號通用設定",
    ["Fenster nicht gefunden"] = "找不到視窗",
    ["(nicht gesetzt)"] = "（未設定）",
    ["WoW-Optionen (accountweit)"] = "WoW 設定（帳號通用）",
    ["Minimap-Icons"] = "小地圖按鈕",
    ["(kein Makro)"] = "（無巨集）",
    ["(leer)"] = "（空）",
    ["Makro-Text:"] = "巨集內容：",
    ["In der Vorlage:"] = "範本中：",
    ["Jetzt:"] = "目前：",
    ["Vorlage:"] = "範本：",
    ["Dieser Char:"] = "此角色：",
    ["Abgewählt: wird nie synchronisiert bzw. nicht verfolgt."] = "已排除：從不同步或追蹤。",
    ["Haken setzen: wieder einbeziehen."] = "勾選以重新包含。",
    ["|cffffd100Vorher:|r %s"] = "|cffffd100之前：|r %s",
    ["|cffffd100Jetzt:|r %s"] = "|cffffd100目前：|r %s",
    ["Zurücksetzen = alten Wert wiederherstellen. Übernehmen = neuen Wert als Stand merken."] = "重設 = 還原舊值。接受 = 將新值記為基準狀態。",
    ["Rechtsklick: diese Einstellung nie verfolgen."] = "右鍵：不再追蹤此設定。",
    ["Intern: %s"] = "內部名稱：%s",
    ["Macht nur diese Änderung der letzten Übernahme rückgängig."] = "只復原上次套用中的這一處變更。",
    ["|cffffd100Vor der Übernahme:|r %s"] = "|cffffd100套用前：|r %s",
    ["Vor der Übernahme:"] = "套用前：",
    ["Seit dem Speichern der Vorlage geändert. Mit „Vorlage aktualisieren“ geht diese Änderung an die anderen Chars."] = "儲存範本後已變更。點擊「更新範本」即可將此變更傳送給其他角色。",
    ["|cffffd100In der Vorlage:|r %s"] = "|cffffd100範本中：|r %s",
    ["|cffffd100Vorlage (%s):|r %s"] = "|cffffd100範本（%s）：|r %s",
    ["|cffffd100Dieser Char:|r %s"] = "|cffffd100此角色：|r %s",
    ["Beim Übernehmen: %s"] = "套用時：%s",
    ["Nicht möglich: %s"] = "無法套用：%s",
    ["Wird nur übernommen, wenn du den Haken ausdrücklich setzt."] = "只有在你明確勾選後才會套用。",
    ["Wird nach einem Neuladen der Oberfläche vollständig aktiv."] = "重新載入介面後才會完全生效。",
    ["Haken entfernen = diese Einstellung nie synchronisieren (gilt für alle Chars)."] = "取消勾選 = 永不同步此設定（適用於所有角色）。",
    ["Alles in diesem Abschnitt anhaken oder abwählen."] = "勾選或取消勾選此區段的全部內容。",
    ["Vorlage für %s"] = "%s的範本",
    ["Allgemeine Vorlage"] = "通用範本",
    ["noch keine"] = "尚無",
    ["(dieser Char)"] = "（此角色）",
    ["%d.%m.%Y um %H:%M"] = "%Y年%m月%d日 %H:%M",
    ["CharSync – Einstellungen auf alle Chars übertragen"] = "CharSync——將設定同步到所有角色",
    ["Als allgemeine Vorlage speichern"] = "儲存為通用範本",
    ["Speichert alle Einstellungen dieses Chars, wie sie gerade sind: die allgemeine Vorlage und die Vorlage seiner Klasse (wenn dieser Char sie stellt). Accountweite Einstellungen bleiben unberührt – die übernimmst du über die Knöpfe unten rechts."] = "依目前狀態儲存此角色的所有設定：通用範本及其職業範本（若由此角色提供）。帳號通用設定保持不變——請用右下角的按鈕接受。",
    ["Als Klassen-Vorlage speichern"] = "儲存為職業範本",
    ["Klassen-Vorlage"] = "職業範本",
    ["Speichert Makros und Aktionsleisten dieses Chars als Vorlage für alle Chars der Klasse %s."] = "將此角色的巨集與快捷列儲存為%s職業所有角色的範本。",
    ["Allgemeiner Vorlage-Char"] = "通用範本角色",
    ["Dieser Char stellt die allgemeine Vorlage. Mit „Vorlage automatisch aktualisieren“ wird sie automatisch gespeichert, sonst per Knopf oder einzeln mit „In Vorlage“."] = "此角色提供通用範本。開啟「自動更新範本」後會自動儲存，否則請用按鈕儲存，或用「寫入範本」逐項儲存。",
    ["Vorlage-Char seiner Klasse"] = "本職業的範本角色",
    ["Dieser Char stellt Makros und Aktionsleisten für seine Klasse. Mit „Vorlage automatisch aktualisieren“ wird diese Vorlage automatisch gespeichert."] = "此角色為其職業提供巨集與快捷列。開啟「自動更新範本」後，此範本會自動儲存。",
    ["Ohne Nachfrage übernehmen"] = "不經確認直接套用",
    ["Neue Vorlagen werden beim Einloggen sofort übernommen, ohne dass sich dieses Fenster zum Prüfen öffnet."] = "登入時立即套用新範本，不會開啟此視窗供你檢查。",
    ["Vorlage automatisch aktualisieren"] = "自動更新範本",
    ["Vorlage-Chars speichern ihre Vorlage einmal pro Minute und beim Ausloggen, wenn sich etwas geändert hat. Standard: aus."] = "範本角色在有變更時，每分鐘一次並在登出時儲存其範本。預設：關閉。",
    ["Minimap-Icon anzeigen"] = "顯示小地圖按鈕",
    ["Zeigt das CharSync-Icon an der Minimap. Ein Klick darauf öffnet dieses Fenster."] = "在小地圖上顯示 CharSync 按鈕。點擊即可開啟此視窗。",
    ["Bereiche"] = "類別",
    ["(gleiche Klasse)"] = "（同職業）",
    ["Verfolgt Einstellungen, die für alle Chars gelten (accountweite Addon-Einstellungen, accountweite WoW-Optionen): Bei jedem Einloggen merkt sich CharSync den Stand, danach erscheint hier jede Änderung mit vorherigem Wert – einzeln übernehmen oder zurücksetzen, ausgewählte oder alle. Standard: aus."] = "追蹤對所有角色生效的設定（帳號通用的插件設定與 WoW 設定）：每次登入時 CharSync 會記住目前狀態，之後每項變更都會連同之前的值顯示在這裡，可逐項、按所選或全部接受或重設。預設：關閉。",
    ["Abgewählte Einstellungen"] = "已排除的設定",
    ["Zeigt am Ende der Liste die Einstellungen, die du abgewählt hast (nie synchronisieren, nie verfolgen). Ein Haken dort holt sie zurück."] = "在清單末尾顯示你排除的設定（從不同步、從不追蹤）。在那裡勾選即可恢復。",
    ["Vergleich: dieser Char » Vorlage"] = "比對：此角色 » 範本",
    ["Alle anhaken"] = "全部勾選",
    ["Hakt alles in der Liste an. Abgewählte Einstellungen bleiben abgewählt."] = "勾選清單中的全部內容。已排除的設定保持排除。",
    ["Keine"] = "全不選",
    ["Entfernt alle Haken in der Liste."] = "取消清單中的所有勾選。",
    ["Angehakte übernehmen"] = "套用已勾選項目",
    ["Übernimmt alles Angehakte: Abweichungen zur Vorlage werden übernommen, accountweite Einstellungen werden der neue Stand, Änderungen seit der Vorlage gehen in die Vorlage."] = "套用所有已勾選項目：與範本的差異會被套用，帳號通用設定成為新的基準狀態，範本儲存後的變更寫入範本。",
    ["Alle übernehmen"] = "全部套用",
    ["Übernimmt alles in der Liste: Abweichungen zur Vorlage (außer nie zu synchronisierenden), accountweite Einstellungen als neuen Stand, Änderungen seit der Vorlage in die Vorlage."] = "套用清單中的全部內容：與範本的差異（永不同步的除外）、帳號通用設定作為新的基準狀態、範本儲存後的變更寫入範本。",
    ["Alle zurücksetzen"] = "全部重設",
    ["Setzt alle zurücksetzbaren Änderungen in der Liste zurück: Änderungen seit der Vorlage, die letzte Übernahme und accountweite Einstellungen."] = "重設清單中所有可重設的變更：範本儲存後的變更、上次套用與帳號通用設定。",
    ["Ausgewählte zurücksetzen"] = "重設所選",
    ["Setzt nur die angehakten Änderungen zurück."] = "只重設已勾選的變更。",
    ["Schließt das Fenster. Beim nächsten Login wirst du wieder gefragt."] = "關閉視窗。下次登入時會再次詢問你。",
    ["Diesmal nichts"] = "這次略過",
    ["Übernimmt nichts und fragt erst wieder, wenn eine neuere Vorlage gespeichert wird."] = "不套用任何內容，直到儲存了較新的範本才會再次詢問。",
    ["Neue Vorlage von %s – prüfe, was übernommen werden soll."] = "來自%s的新範本——請檢查要套用哪些內容。",
    ["Einstellungen dieses Chars (%s, %s)"] = "此角色的設定（%s，%s）",
    ["Als Vorlage für %s speichern"] = "儲存為%s的範本",
    ["Vorlage-Char für %s"] = "%s的範本角色",
    ["Letzte Übernahme vom %s"] = "上次套用：%s",
    ["Alles rückgängig"] = "全部復原",
    ["Macht alle Änderungen der letzten Übernahme rückgängig, die noch bestehen."] = "復原上次套用中仍然存在的所有變更。",
    ["|cffffd100Vor der Übernahme:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100套用前：|r |cff90ff90%s|r   »   |cffffd100目前：|r |cffff9090%s|r",
    ["Rückgängig"] = "復原",
    ["(Klassen-Vorlage)"] = "（職業範本）",
    ["(seit der Vorlage geändert)"] = "（範本儲存後已變更）",
    ["In Vorlage"] = "寫入範本",
    ["Übernimmt nur diese Änderung in die Vorlage. Die anderen Chars bekommen sie beim nächsten Login angezeigt."] = "只將此變更寫入範本。其他角色會在下次登入時看到。",
    ["Zurücksetzen"] = "重設",
    ["Setzt nur diese Einstellung bei diesem Char auf den Stand der Vorlage zurück."] = "只將此角色的這項設定重設為範本狀態。",
    ["|cffffd100In der Vorlage:|r %s   »   |cffffd100Jetzt:|r %s"] = "|cffffd100範本中：|r %s   »   |cffffd100目前：|r %s",
    ["|cffffd100Vorlage:|r |cff90ff90%s|r   »   |cffffd100Dieser Char:|r |cffff9090%s|r"] = "|cffffd100範本：|r |cff90ff90%s|r   »   |cffffd100此角色：|r |cffff9090%s|r",
    ["(seit dem Einloggen um %s)"] = "（自 %s 登入起）",
    ["Wird gelesen …"] = "正在讀取……",
    ["Keine Änderungen seit dem Einloggen."] = "自登入以來沒有變更。",
    ["|cffffd100Vorher:|r |cff90ff90%s|r   »   |cffffd100Jetzt:|r |cffff9090%s|r"] = "|cffffd100之前：|r |cff90ff90%s|r   »   |cffffd100目前：|r |cffff9090%s|r",
    ["Gilt für alle Chars. Rechtsklick: nie verfolgen."] = "對所有角色生效。右鍵：不再追蹤。",
    ["Übernehmen"] = "接受",
    ["Merkt sich den neuen Wert als Stand; die Zeile verschwindet."] = "將新值記為基準狀態；該行會消失。",
    ["Stellt den vorherigen Wert wieder her."] = "還原之前的值。",
    ["Abgewählt (%d)"] = "已排除 (%d)",
    ["Noch keine Vorlage gespeichert. Log dich mit dem Char ein, dessen Einstellungen für alle gelten sollen, und klick links auf „Als allgemeine Vorlage speichern“. Für Makros und Aktionsleisten speicherst du je Klasse eine Klassen-Vorlage."] = "尚未儲存範本。請以你希望其設定套用到所有角色的那個角色登入，然後點擊左側的「儲存為通用範本」。巨集與快捷列則請為每個職業各儲存一個職業範本。",
    ["Keine Abweichungen – dieser Char entspricht den Vorlagen."] = "沒有差異——此角色與範本一致。",
    ["%d Abweichungen, %d angehakt"] = "%d處差異，已勾選%d處",
    ["%d Änderungen seit der Vorlage"] = "範本儲存後有 %d 處變更",
    ["%d accountweit"] = "帳號通用 %d 項",
    ["%d Einstellung(en) abgewählt"] = "已取消勾選 %d 項設定",
    ["%d Änderung(en) übernommen."] = "已接受 %d 處變更。",
    ["Speichert die Einstellungen des aktuellen Chars als Vorlage und überträgt sie auf die anderen Chars, sobald diese sich einloggen. Makros und Aktionsleisten gehen nur an Chars derselben Klasse. Vor dem Übernehmen siehst du für jede Einstellung vorher und nachher und kannst sie einzeln abwählen.\n\nBefehle: /charsync (Fenster), /charsync save (allgemeine Vorlage), /charsync saveclass (Klassen-Vorlage), /charsync apply (übernehmen)"] = "將目前角色的設定儲存為範本，並在你的其他角色登入時同步給它們。巨集與快捷列只會同步給同職業的角色。套用前，你可以看到每項設定的之前與之後，並可逐項取消勾選。\n\n指令：/charsync（視窗）、/charsync save（通用範本）、/charsync saveclass（職業範本）、/charsync apply（套用）",
    ["CharSync-Fenster öffnen"] = "開啟CharSync視窗",
    ["Neue Vorlage zum Prüfen"] = "有新範本待檢查",
    ["Klicken: Fenster öffnen"] = "點擊：開啟視窗",
    ["Ziehen: Icon verschieben"] = "拖曳：移動按鈕",
    ["Minimap-Icon zurückgesetzt."] = "小地圖按鈕已重置。",
